var DERSLER = [
// ---------------- DERS 92 ----------------
{ no: 92, kisa: "مَفْهومُ الأَمْنِ", ar: "القِراءَةُ المُكَثَّفَةُ: مَفْهومُ الأَمْنِ", tr: "Yoğun okuma: Güven kavramı", ozet: "Güvenin büyük bir nimet oluşu, insan canının dokunulmazlığı, nefsin hayır ve şer eğilimleri ve İslâm’ın kapsamlı güveni sağlayan kuralları.", bloklar: [
 { t: "hazirlik", ar: "ما قَبْلَ القِراءَةِ: فَكِّرْ فِي الإِجابَةِ عَنْ هذِهِ الأَسْئِلَةِ قَبْلَ قِراءَةِ القِطْعَةِ", ogeler: [["ما أَكْثَرُ البُلْدانِ أَمْنًا فِي العالَمِ؟ مَا الَّذي يَجْعَلُها آمِنَةً؟", "Dünyanın en güvenli ülkeleri hangileri? Onları güvenli kılan nedir?"], ["ما رَأْيُكَ في شَخْصٍ أَعْطاهُ اللهُ أَمْوالًا كَثيرَةً وَحَرَمَهُ نِعْمَةَ الأَمْنِ؟", "Allah’ın çok mal verip güven nimetinden mahrum bıraktığı kişi hakkında ne düşünüyorsun?"], ["ما رَأْيُكَ في شَخْصٍ أَعْطاهُ اللهُ المالَ وَالصِّحَّةَ وَحَرَمَهُ نِعْمَةَ الأَمْنِ؟", "Allah’ın mal ve sağlık verip güven nimetinden mahrum bıraktığı kişi hakkında ne düşünüyorsun?"], ["مَنْ أَحَقُّ بِالأَمْنِ: المُؤْمِنُ أَمِ الكافِرُ؟ وَلِماذا؟", "Güvene kim daha layık: mümin mi kâfir mi? Niçin?"]] },
 { t: "metin", resim: ["kure"], paragraf: [[["الأَمْنُ فِي الدُّنْيا نِعْمَةٌ مِنَ النِّعَمِ الكُبْرى، الَّتي مَنَّ اللهُ بِها عَلى عِبادِهِ المُؤْمِنينَ الصّالِحينَ؛ فَهُوَ سَبيلٌ لِلرّاحَةِ وَالطُّمَأْنينَةِ، وَطَريقٌ لِلرَّخاءِ وَالاسْتِقْرارِ. قالَ تَعالى: ﴿فَلْيَعْبُدوا رَبَّ هذَا البَيْتِ * الَّذي أَطْعَمَهُمْ مِنْ جوعٍ وَآمَنَهُمْ مِنْ خَوْفٍ﴾. وَوَعَدَ اللهُ رَسولَهُ ﷺ أَنْ يَجْعَلَ المُؤْمِنينَ خُلَفاءَ فِي الأَرْضِ، أَئِمَّةً لِلنّاسِ هُداةً مُهْتَدينَ، وَأَنْ يُوَفِّرَ لَهُمُ الأَمْنَ مِنْ بَعْدِ الخَوْفِ. قالَ تَعالى: ﴿وَعَدَ اللهُ الَّذينَ آمَنوا مِنْكُمْ وَعَمِلُوا الصّالِحاتِ لَيَسْتَخْلِفَنَّهُمْ فِي الأَرْضِ كَمَا اسْتَخْلَفَ الَّذينَ مِنْ قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دينَهُمُ الَّذِي ارْتَضى لَهُمْ وَلَيُبَدِّلَنَّهُمْ مِنْ بَعْدِ خَوْفِهِمْ أَمْنًا يَعْبُدونَني لا يُشْرِكونَ بي شَيْئًا وَمَنْ كَفَرَ بَعْدَ ذلِكَ فَأُولئِكَ هُمُ الفاسِقونَ﴾.", "Dünyada güven, Allah’ın salih mümin kullarına lütfettiği büyük nimetlerden biridir; rahatlığa ve huzura giden bir yol, refaha ve istikrara giden bir yoldur. Allah Teâlâ buyurdu: «Öyleyse kendilerini açlıktan doyuran ve korkudan emin kılan bu evin Rabbine ibadet etsinler.» Allah, Resûlü’ne (s.a.v.) müminleri yeryüzünde halifeler, insanlara doğru yolu gösteren ve doğru yolda olan önderler kılacağını ve onlara korkudan sonra güven sağlayacağını vadetti. Allah Teâlâ buyurdu: «Allah, içinizden iman edip salih ameller işleyenlere, kendilerinden öncekileri halife kıldığı gibi onları da yeryüzünde halife kılacağını, onlar için razı olduğu dinlerini sağlamlaştıracağını ve korkularından sonra onları güvene kavuşturacağını vadetti. Bana ibadet ederler, hiçbir şeyi bana ortak koşmazlar. Bundan sonra kim inkâr ederse işte onlar fasıklardır.»", "m92-0"]], [["إِنَّ الأَمْنَ الَّذي وَعَدَ اللهُ بِهِ رَسولَهُ الكَريمَ ﷺ وَعِبادَهُ المُؤْمِنينَ، الَّذينَ يَعْمَلونَ الصّالِحاتِ، لا يُقَدَّرُ بِثَمَنٍ في حَياةِ الأَفْرادِ وَالشُّعوبِ؛ فَهُوَ سَبَبُ السَّعادَةِ وَالاسْتِقْرارِ. قالَ تَعالى: ﴿وَضَرَبَ اللهُ مَثَلًا قَرْيَةً كانَتْ آمِنَةً مُطْمَئِنَّةً يَأْتيها رِزْقُها رَغَدًا مِنْ كُلِّ مَكانٍ فَكَفَرَتْ بِأَنْعُمِ اللهِ فَأَذاقَهَا اللهُ لِباسَ الجوعِ وَالخَوْفِ بِما كانوا يَصْنَعونَ﴾.", "Allah’ın değerli Resûlü’ne (s.a.v.) ve salih amel işleyen mümin kullarına vadettiği güven, fertlerin ve halkların hayatında paha biçilmezdir; çünkü o, mutluluğun ve istikrarın sebebidir. Allah Teâlâ buyurdu: «Allah, güvenli ve huzurlu olan, rızkı her yerden bol bol gelen bir şehri misal verdi. Ama o, Allah’ın nimetlerine nankörlük etti; Allah da yaptıklarından dolayı ona açlık ve korku elbisesini tattırdı.»", "m92-1"]], [["حَرَّمَ اللهُ سُبْحانَهُ وَتَعالى نَفْسَ المُؤْمِنِ عَلى صاحِبِها، وَحَرَّمَها عَلى غَيْرِهِ مِنَ البَشَرِ، فَلا يَجوزُ الاعْتِداءُ عَلَيْها وَقَتْلُها أَوْ إيذاؤُها، وَجَعَلَ عُقوبَةَ مَنْ يَقْتُلُهَا النّارَ فِي الآخِرَةِ، تَكْريمًا وَصِيانَةً لِهذِهِ النَّفْسِ البَشَرِيَّةِ. قالَ تَعالى: ﴿وَلا تَقْتُلُوا النَّفْسَ الَّتي حَرَّمَ اللهُ إِلّا بِالحَقِّ﴾. وَقالَ تَعالى: ﴿وَلا تُلْقوا بِأَيْديكُمْ إِلَى التَّهْلُكَةِ﴾. وَقالَ رَسولُ اللهِ ﷺ في خُطْبَةِ الوَداعِ: «أَيُّهَا النّاسُ، إِنَّ دِماءَكُمْ وَأَمْوالَكُمْ عَلَيْكُمْ حَرامٌ كَحُرْمَةِ يَوْمِكُمْ هذا، في شَهْرِكُمْ هذا، في بَلَدِكُمْ هذا».", "Allah Teâlâ müminin canını hem sahibine hem de diğer insanlara haram kıldı; ona saldırmak, onu öldürmek veya ona eziyet etmek caiz değildir. Bu insan canını onurlandırmak ve korumak için onu öldürenin cezasını ahirette ateş kıldı. Allah Teâlâ buyurdu: «Allah’ın haram kıldığı cana haksız yere kıymayın.» Yine buyurdu: «Kendi ellerinizle kendinizi tehlikeye atmayın.» Resûlullah (s.a.v.) Veda Hutbesi’nde buyurdu: «Ey insanlar! Bu gününüz, bu ayınız ve bu beldeniz nasıl haram ise kanlarınız ve mallarınız da öylece size haramdır.»", "m92-2"]], [["وَالنَّفْسُ البَشَرِيَّةُ لَها دَوافِعُها لِلْخَيْرِ وَالشَّرِّ، وَهِيَ بِحُكْمِ طَبيعَتِها تَميلُ إِلى ما تَطْمَحُ إِلَيْهِ، وَتَتَطَلَّعُ إِلى ما لَمْ تَصِلْ إِلَيْهِ خَيْرًا كانَ أَوْ شَرًّا. وَالأَمْنُ يَرْتَبِطُ غالِبًا بِنَزْعَةِ الخَيْرِ عِنْدَ الإِنْسانِ، وَالجَريمَةُ تَرْتَبِطُ غالِبًا بِنَزْعَةِ الشَّرِّ عِنْدَهُ. قالَ تَعالى: ﴿وَنَفْسٍ وَما سَوّاها * فَأَلْهَمَها فُجورَها وَتَقْواها﴾.", "İnsan nefsinin hayra ve şerre yönelten güdüleri vardır; tabiatı gereği arzu ettiği şeye meyleder ve hayır olsun şer olsun ulaşamadığı şeye göz diker. Güven çoğunlukla insandaki hayır eğilimine, suç ise çoğunlukla şer eğilimine bağlıdır. Allah Teâlâ buyurdu: «Nefse ve onu düzenleyene, sonra ona kötülüğünü ve takvasını ilham edene andolsun.»", "m92-3"]], [["وَالإِسْلامُ لَمْ يَتْرُكْ صَغيرَةً وَلا كَبيرَةً مِنْ سُلوكِ العِبادِ، إِلّا وَضَعَ لَها قَواعِدَ وَأُسُسًا تَتَّفِقُ مَعَ مَصْلَحَةِ الفَرْدِ وَالجَماعَةِ، سَواءٌ أَكانَ هذَا السُّلوكُ عِبادَةً أَمْ مُعامَلَةً، وَقَرَّرَ عُقوبَةً لِكُلِّ فِعْلٍ لا يَتَّفِقُ مَعَ مَصْلَحَةِ الجَماعَةِ وَالفَرْدِ؛ فَتَحَقَّقَ بِذلِكَ الأَمْنُ الذّاتِيُّ، وَالأَمْنُ فِي المالِ، وَالأَمْنُ فِي النَّسْلِ وَالعِرْضِ، وَالأَمْنُ فِي المُعامَلاتِ، وَالأَمْنُ فِي الحُقوقِ الخاصَّةِ وَالعامَّةِ، وَالأَمْنُ في كَسْبِ العَيْشِ الحَلالِ.", "İslâm, kulların davranışlarından küçük büyük hiçbir şeyi, ibadet olsun muamele olsun, fert ve toplumun maslahatına uygun kurallar ve esaslar koymadan bırakmadı; toplumun ve ferdin maslahatına uymayan her fiil için bir ceza belirledi. Böylece kişisel güvenlik, malda güvenlik, nesilde ve namusta güvenlik, muamelelerde güvenlik, özel ve kamusal haklarda güvenlik ve helal kazançta güvenlik gerçekleşti.", "m92-4"]], [["لَقَدْ أَرادَ اللهُ سُبْحانَهُ وَتَعالى بِهذَا الأَمْنِ الشّامِلِ حَياةً كَريمَةً لِلْفَرْدِ وَالجَماعَةِ، حَياةً مُسْتَقِرَّةً آمِنَةً، هادِئَةً، لا يُعَكِّرُها سُلوكُ العابِثينَ وَالمُنْحَرِفينَ وَالمُجْرِمينَ؛ فَقَرَّرَ الخالِقُ لِكُلِّ عَمَلٍ مُخِلٍّ بِأَمْنِ الفَرْدِ وَالجَماعَةِ عُقوبَةً رادِعَةً لِمَنْ لا يَمْتَثِلُ لِأَوامِرِ اللهِ، وَلا يَنْتَهي بِنَواهيهِ، وَلا يَحْرِصُ عَلى مَصْلَحَةِ الجَماعَةِ الَّتي يَنْتَمي إِلَيْها؛ فَجَعَلَ حَدَّ القِصاصِ لِلْقاتِلِ المُتَعَمِّدِ. قالَ تَعالى: ﴿وَلَكُمْ فِي القِصاصِ حَياةٌ يا أُولِي الأَلْبابِ لَعَلَّكُمْ تَتَّقونَ﴾.", "Allah Teâlâ bu kapsamlı güvenle fert ve toplum için onurlu bir hayat istedi: istikrarlı, güvenli, sakin, sorumsuzların, sapkınların ve suçluların davranışlarının bulandırmadığı bir hayat. Bu yüzden Yaratıcı, fert ve toplumun güvenliğini bozan her iş için, Allah’ın emirlerine uymayan, yasaklarından kaçınmayan ve mensubu olduğu toplumun maslahatını gözetmeyen kimseye caydırıcı bir ceza koydu; kasten öldüren için kısas haddini belirledi. Allah Teâlâ buyurdu: «Ey akıl sahipleri! Kısasta sizin için hayat vardır; umulur ki sakınırsınız.»", "m92-5"]]] },
 { t: "dy", ar: "اسْتيعابٌ — تَدْريبٌ ١: ضَعْ عَلامَةَ (✓) أَوْ (✗) ثُمَّ صَحِّحِ الخَطَأَ", ogeler: [["الأَمْنُ نِعْمَةٌ مَنَحَهَا اللهُ لِلْمُؤْمِنينَ الصّالِحينَ.", true, "", "Güven, Allah’ın salih müminlere verdiği bir nimettir."], ["الشَّرْطُ الَّذي وَضَعَهُ اللهُ لِلأَمْنِ هُوَ أَلّا يُشْرَكَ بِهِ شَيْئًا.", true, "", "Allah’ın güven için koyduğu şart, O’na hiçbir şeyin ortak koşulmamasıdır.", "Âyette: «يَعْبُدونَني لا يُشْرِكونَ بي شَيْئًا»."], ["يَرْتَبِطُ الأَمْنُ بِنَزْعَةِ الخَوْفِ عِنْدَ الإِنْسانِ.", false, "يَرْتَبِطُ الأَمْنُ غالِبًا بِنَزْعَةِ الخَيْرِ عِنْدَ الإِنْسانِ.", "Güven insandaki korku eğilimine bağlıdır."], ["السِّجْنُ عُقوبَةُ القاتِلِ المُتَعَمِّدِ فِي الإِسْلامِ.", false, "عُقوبَتُهُ القِصاصُ.", "İslâm’da kasten öldürenin cezası hapistir."], ["عُقوبَةُ القاتِلِ فِي الآخِرَةِ دُخولُ النّارِ.", true, "", "Katilin ahiretteki cezası ateşe girmektir."]] },
 { t: "secim", ar: "تَدْريبٌ ٢: اخْتَرِ الجَوابَ الصَّحيحَ", ogeler: [["أَهَمُّ النِّعَمِ الَّتي ذُكِرَتْ فِي الفِقْرَةِ الأولى ...", "الأَمْنُ وَالطَّعامُ", ["الأَمْنُ وَالصِّحَّةُ", "الأَمْنُ وَالمالُ"], "Birinci paragrafta anılan en önemli nimetler …", "Âyette: «أَطْعَمَهُمْ مِنْ جوعٍ وَآمَنَهُمْ مِنْ خَوْفٍ»."], ["ما سَبَبُ السَّعادَةِ وَالاسْتِقْرارِ؟", "الأَمْنُ", ["المالُ", "كَسْبُ العَيْشِ الحَلالِ"], "Mutluluğun ve istikrarın sebebi nedir?"], ["تَتَطَلَّعُ النَّفْسُ البَشَرِيَّةُ إِلى ...", "الخَيْرِ وَالشَّرِّ", ["الخَيْرِ", "الشَّرِّ"], "İnsan nefsi … göz diker."], ["بِأَيِّ نَزْعَةٍ تَرْتَبِطُ الجَريمَةُ عِنْدَ الإِنْسانِ؟", "بِنَزْعَةِ الشَّرِّ", ["بِنَزْعَةِ الخَيْرِ", "بِنَزْعَةِ الخَيْرِ وَالشَّرِّ"], "Suç insanda hangi eğilime bağlıdır?"], ["شَرَعَ اللهُ - سُبْحانَهُ وَتَعالى - لِكُلِّ عَمَلٍ مُخِلٍّ بِالأَمْنِ ...", "عُقوبَةً رادِعَةً", ["عُقوبَةَ النّارِ", "عُقوبَةَ القَتْلِ"], "Allah güveni bozan her iş için … koydu."]] },
 { t: "acik", ar: "تَدْريبٌ ٣: أَجِبْ بِاخْتِصارٍ عَمّا يَلي", aciklama: "Kısaca cevapla; sonra cevaba bak.", ogeler: [["لِماذا لا يَجوزُ أَنْ يَقْتُلَ المُؤْمِنُ نَفْسَهُ؟", "لِأَنَّ اللهَ حَرَّمَ نَفْسَ المُؤْمِنِ عَلى صاحِبِها، وَقالَ: ﴿وَلا تُلْقوا بِأَيْديكُمْ إِلَى التَّهْلُكَةِ﴾.", "Mümin niçin kendini öldüremez?"], ["لِماذا جَعَلَ اللهُ عُقوبَةَ القاتِلِ النّارَ فِي الآخِرَةِ؟", "تَكْريمًا وَصِيانَةً لِلنَّفْسِ البَشَرِيَّةِ.", "Allah katilin cezasını niçin ahirette ateş kıldı?"], ["مَتى يَكونُ قَتْلُ النَّفْسِ حَلالًا؟", "إِذا كانَ بِالحَقِّ، كَالقِصاصِ مِنَ القاتِلِ المُتَعَمِّدِ.", "Can almak ne zaman helal olur?"], ["لِماذا يَتَحَقَّقُ الأَمْنُ الذّاتِيُّ عِنْدَ المُسْلِمينَ؟", "لِأَنَّ الإِسْلامَ وَضَعَ لِسُلوكِهِمْ قَواعِدَ تَتَّفِقُ مَعَ مَصْلَحَةِ الفَرْدِ وَالجَماعَةِ، وَقَرَّرَ عُقوبَةً لِكُلِّ فِعْلٍ يُخالِفُها.", "Müslümanlarda kişisel güvenlik niçin gerçekleşir?"], ["إِلى أَيِّ شَيْءٍ تَميلُ النَّفْسُ البَشَرِيَّةُ؟", "تَميلُ إِلى ما تَطْمَحُ إِلَيْهِ، وَتَتَطَلَّعُ إِلى ما لَمْ تَصِلْ إِلَيْهِ، خَيْرًا كانَ أَوْ شَرًّا.", "İnsan nefsi neye meyleder?"]] },
 { t: "esle", ar: "مُفْرَداتٌ — تَدْريبٌ ١: هاتِ جَمْعَ الكَلِماتِ التّالِيَةِ (وَيُمْكِنُكَ الاسْتِعانَةُ بِالنَّصِّ)", ciftler: [["مالٌ", "أَمْوالٌ", "mal"], ["قاعِدَةٌ", "قَواعِدُ", "kural"], ["حَقٌّ", "حُقوقٌ", "hak"], ["أَمْرٌ", "أَوامِرُ / أُمورٌ", "emir; iş"], ["فَرْدٌ", "أَفْرادٌ", "fert"], ["نِعْمَةٌ", "نِعَمٌ / أَنْعُمٌ", "nimet"], ["دَمٌ", "دِماءٌ", "kan"], ["أَساسٌ", "أُسُسٌ", "temel"], ["إِمامٌ", "أَئِمَّةٌ", "önder"], ["دافِعٌ", "دَوافِعُ", "güdü"], ["الهادي", "الهُداةُ", "yol gösteren"], ["عَبْدٌ", "عِبادٌ", "kul"]] },
 { t: "esle", ar: "تَدْريبٌ ٢: صِلْ بَيْنَ الكَلِمَتَيْنِ اللَّتَيْنِ تَأْتِيانِ مَعًا", ciftler: [["الدُّنْيا", "الآخِرَةُ", "dünya – ahiret"], ["الخَيْرُ", "الشَّرُّ", "hayır – şer"], ["خَوْفٌ", "أَمْنٌ", "korku – güven"], ["الفُجورُ", "التَّقْوى", "kötülük – takva"], ["الخاصُّ", "العامُّ", "özel – genel"], ["كُبْرى", "صُغْرى", "büyük – küçük"], ["الأَوامِرُ", "النَّواهي", "emirler – yasaklar"], ["الفَرْدُ", "الجَماعَةُ", "fert – toplum"]] },
 { t: "acik", ar: "تَدْريبٌ ٣: ما مَعاني العِباراتِ التّالِيَةِ؟ اسْتَعِنْ بِمُعْجَمٍ عَرَبِيٍّ", aciklama: "İfadelerin anlamını Arapça açıkla.", ogeler: [["مَنَّ اللهُ عَلَيْهِ بِنِعَمٍ كَثيرَةٍ", "أَنْعَمَ عَلَيْهِ وَتَفَضَّلَ بِنِعَمٍ كَثيرَةٍ.", "Allah ona birçok nimet lütfetti."], ["اسْتَخْلَفَهُ فِي الأَرْضِ", "جَعَلَهُ خَليفَةً يَحْكُمُ وَيَعْمُرُ الأَرْضَ بَعْدَ غَيْرِهِ.", "Onu yeryüzünde halife kıldı."], ["مَكَّنَ لَهُ دينَهُ", "ثَبَّتَهُ وَقَوّاهُ وَنَشَرَهُ.", "Onun dinini sağlamlaştırdı."], ["لا يُقَدَّرُ بِثَمَنٍ", "غالٍ جِدًّا، لا يُساويهِ أَيُّ ثَمَنٍ.", "Paha biçilmez."], ["ضَرَبَ مَثَلًا", "ذَكَرَ مِثالًا لِلتَّوْضيحِ وَالعِبْرَةِ.", "Misal verdi."], ["أَلْقى بِيَدِهِ إِلَى التَّهْلُكَةِ", "عَرَّضَ نَفْسَهُ لِلْهَلاكِ.", "Kendi eliyle kendini tehlikeye attı."]] },
 { t: "kural", ar: "فائِدَةٌ (١٤)", metin: "هُناكَ نَوْعانِ مِنَ التَّلْخيصِ: مُرَكَّزٌ وَعادِيٌّ. فِي التَّلْخيصِ المُرَكَّزِ يَنْبَغي أَلّا يَزيدَ طولُ المُلَخَّصِ عَلى ٢٥٪ مِنْ طولِ النَّصِّ كُلِّهِ، وَلكِنْ يُمْكِنُ أَنْ يَكونَ أَقَلَّ بِقَليلٍ مِنْ ذلِكَ. وَمِنَ الضَّرورَةِ أَنْ يَكونَ هذَا المُلَخَّصُ المُرَكَّزُ ذا عِباراتٍ وَجُمَلٍ قَصيرَةٍ واضِحَةِ المَعاني، وَأَنْ يُعْطِيَ لُبَّ المَعْنَى المُتَضَمَّنِ فِي المَوْضوعِ الأَصْلِيِّ، بِالإِضافَةِ إِلَى السَّلامَةِ اللُّغَوِيَّةِ.", tr: "İki tür özet vardır: yoğun ve normal. Yoğun özette özetin uzunluğu metnin tamamının %25’ini geçmemeli, biraz daha az olabilir. Bu özet kısa, anlamı açık ifade ve cümlelerden oluşmalı, asıl konunun özünü vermeli ve dilce de doğru olmalıdır." },
 { t: "acik", ar: "الكِتابَةُ: أَعِدْ قِراءَةَ النَّصِّ السّابِقِ، وَاكْتُبْ مُلَخَّصًا لَهُ", aciklama: "Önce kendin yaz (metnin en çok %25’i kadar); sonra örnek özete bak.", ogeler: [["مُلَخَّصُ: مَفْهومُ الأَمْنِ", "الأَمْنُ نِعْمَةٌ كُبْرى وَعَدَ اللهُ بِها المُؤْمِنينَ الصّالِحينَ، وَهُوَ سَبَبُ السَّعادَةِ وَالاسْتِقْرارِ. وَقَدْ حَرَّمَ الإِسْلامُ الاعْتِداءَ عَلَى النَّفْسِ، وَجَعَلَ عُقوبَةَ القاتِلِ النّارَ. وَالنَّفْسُ تَميلُ إِلَى الخَيْرِ وَالشَّرِّ؛ فَوَضَعَ الإِسْلامُ قَواعِدَ لِكُلِّ سُلوكٍ، وَقَرَّرَ عُقوباتٍ رادِعَةً كَالقِصاصِ؛ لِيَتَحَقَّقَ الأَمْنُ الشّامِلُ لِلْفَرْدِ وَالجَماعَةِ.", "Örnek yoğun özet"]] }
] },
// ---------------- DERS 93 ----------------
{ no: 93, kisa: "الجُمَلُ الَّتي لَها مَحَلٌّ", ar: "قَواعِدُ اللُّغَةِ (أ): الجُمَلُ الَّتي لَها مَحَلٌّ مِنَ الإِعْرابِ", tr: "Dilbilgisi: İrabda mahalli olan cümleler", ozet: "Haber, hâl, mef‘ûl, sıfat, muzâfun ileyh, fa veya izâ ile gelen şart cevabı ve bunlara tâbi cümleler.", bloklar: [
 { t: "tablo", ar: "الجُمَلُ الَّتي لَها مَحَلٌّ مِنَ الإِعْرابِ", bas: ["النَّوْعُ", "الضّابِطُ", "أَمْثِلَةٌ"], satir: [["الجُمْلَةُ الخَبَرِيَّةُ", "سَواءٌ وَقَعَتْ خَبَرًا لِلْمُبْتَدَإِ، أَوْ خَبَرًا لِكانَ أَوْ إِحْدى أَخَواتِها، أَوْ خَبَرًا لِإِنَّ أَوْ إِحْدى أَخَواتِها. وَيَجِبُ أَنْ تَشْتَمِلَ عَلى ضَميرٍ يَرْبِطُها بِالمُبْتَدَإِ.", "مُحَمَّدٌ [[عِلْمُهُ كَثيرٌ]]. / كانَ الرَّجُلُ [[يَقومُ اللَّيْلَ]]. / إِنَّ المُسْلِمَ [[يُحِبُّ أَخاهُ]]."], ["الجُمْلَةُ الحالِيَّةُ", "الجُمَلُ بَعْدَ المَعارِفِ أَحْوالٌ، وَلا بُدَّ لِجُمْلَةِ الحالِ مِنْ رابِطٍ يَرْبِطُها بِصاحِبِ الحالِ الَّذي لا يَكونُ إِلّا مَعْرِفَةً، وَالرّابِطُ هُوَ الواوُ أَوِ الضَّميرُ أَوْ هُما مَعًا.", "جاءَ الرَّجُلُ [[وَيَدُهُ مَكْسورَةٌ]]. / رَأَيْتُ الطِّفْلَ [[يَلْعَبُ]]."], ["الجُمْلَةُ المَفْعولِيَّةُ", "بَعْدَ القَوْلِ أَوْ غَيْرِهِ.", "قالَ المُعَلِّمُ: [[اكْتُبُوا الواجِبَ]]."], ["جُمْلَةُ الصِّفَةِ", "الجُمَلُ بَعْدَ النَّكِراتِ صِفاتٌ.", "جاءَ رَجُلٌ [[قَلْبُهُ كَبيرٌ]]. / رَأَيْتُ طِفْلًا [[يَلْعَبُ]]."], ["جُمْلَةُ المُضافِ إِلَيْهِ", "وَهِيَ الجُمْلَةُ الواقِعَةُ بَعْدَ حَيْثُ، أَوْ إِذْ، أَوْ إِذا.", "ذَهَبْتُ إِلى حَيْثُ [[يُقامُ الحَفْلُ]]. / اجْلِسْ حَيْثُ [[تَسْتَفيدُ]]. / سِرْتُ إِذِ [[المَطَرُ هاطِلٌ]]. / أُجيبُكَ إِذا [[دَعَوْتَني]]."], ["جُمْلَةُ جَوابِ الشَّرْطِ الجازِمِ المَقْرونَةُ بِالفاءِ أَوْ إِذا", "أَمّا إِذا لَمْ تَقْتَرِنْ بِهِما فَلا مَحَلَّ لَها مِنَ الإِعْرابِ.", "إِنْ صَبَرْتَ [[فَسَتَظْفَرُ بِالفَلاحِ]]. / ﴿وَإِنْ تُصِبْهُمْ سَيِّئَةٌ بِما قَدَّمَتْ أَيْديهِمْ [[إِذا هُمْ يَقْنَطونَ]]﴾"], ["الجُمْلَةُ التّابِعَةُ لِجُمْلَةٍ لَها مَحَلٌّ مِنَ الإِعْرابِ", "تَأْخُذُ حُكْمَ الجُمْلَةِ الَّتي تَتْبَعُها.", "مُحَمَّدٌ عِلْمُهُ كَثيرٌ [[وَقَلْبُهُ نَظيفٌ]]. / المُؤْمِنُ يَذْكُرُ [[وَيَشْكُرُ]]."]],
  not: "Haber, sıfat ve ona tâbi cümleler, bağlı oldukları kelimenin irabını alır; hâl ve mef‘ûl cümlesi nasb, muzâfun ileyh cümlesi cer, fa/izâ ile gelen şart cevabı cezm mahallindedir." },
 { t: "acik", ar: "تَدْريبٌ ١: بَيِّنْ نَوْعَ الجُمَلِ الَّتي تَحْتَها خَطٌّ، وَمَوْقِعَها مِنَ الإِعْرابِ", aciklama: "Altı çizili cümlenin türünü ve irabdaki yerini söyle.", ogeler: [["﴿وَما كانَ اللهُ مُعَذِّبَهُمْ [[وَهُمْ يَسْتَغْفِرونَ]]﴾", "جُمْلَةٌ حالِيَّةٌ (الرّابِطُ: الواوُ وَالضَّميرُ)، في مَحَلِّ نَصْبٍ.", "Hâl cümlesi"], ["﴿وَلكِنَّ أَكْثَرَهُمْ [[لا يَشْكُرونَ]]﴾", "جُمْلَةٌ خَبَرِيَّةٌ؛ خَبَرُ لكِنَّ في مَحَلِّ رَفْعٍ.", "Haber cümlesi"], ["﴿وَأَوْحَيْنا إِلى موسى وَأَخيهِ أَنْ [[تَبَوَّءا لِقَوْمِكُما بِمِصْرَ بُيوتًا]]﴾", "جُمْلَةٌ تَفْسيرِيَّةٌ (بَعْدَ «أَنِ» التَّفْسيرِيَّةِ) لا مَحَلَّ لَها مِنَ الإِعْرابِ.", "Tefsir cümlesi", "Bu cümle bu dersin konusuna değil, mahalli olmayan cümlelere (96. ders) girer: «أَنْ» burada vahyin içeriğini açıklayan tefsir edatıdır."], ["﴿فَسَوْفَ تَعْلَمونَ مَنْ يَأْتيهِ عَذابٌ [[يُخْزيهِ]]﴾", "جُمْلَةُ صِفَةٍ لِـ«عَذابٌ» (نَكِرَةٌ)، في مَحَلِّ رَفْعٍ.", "Sıfat cümlesi"], ["﴿وَجاءَ رَجُلٌ مِنْ أَقْصَى المَدينَةِ [[يَسْعى]]﴾", "جُمْلَةُ صِفَةٍ لِـ«رَجُلٌ» (نَكِرَةٌ)، في مَحَلِّ رَفْعٍ.", "Sıfat cümlesi", "«رَجُلٌ» «مِنْ أَقْصَى المَدينَةِ» ile nitelendiği için bazı nahivciler «يَسْعى»yı hâl (mahallen mansûb) da sayar."], ["كانَ - رَحِمَهُ اللهُ - [[يَقومُ اللَّيْلَ]].", "جُمْلَةٌ خَبَرِيَّةٌ؛ خَبَرُ كانَ في مَحَلِّ نَصْبٍ.", "Haber cümlesi", "«رَحِمَهُ اللهُ» ise ara (i‘tirâzî) cümledir, mahalli yoktur."], ["يَسُرُّني أَنَّكَ [[قَوِيٌّ أَمينٌ]].", "«قَوِيٌّ» خَبَرُ أَنَّ مَرْفوعٌ، وَ«أَمينٌ» خَبَرٌ ثانٍ؛ وَالمَصْدَرُ المُؤَوَّلُ «أَنَّكَ قَوِيٌّ أَمينٌ» في مَحَلِّ رَفْعٍ فاعِلٌ لِـ«يَسُرُّ».", "Haber", "Altı çizili kısım cümle değil, müfred haberdir; cümle değeri taşıyan, «أَنَّ» ile kurulan masdar-ı müevveldir (fâil, merfû‘ mahallinde)."], ["اجْلِسْ حَيْثُ [[يَأْمُرُكَ أُسْتاذُكَ]].", "جُمْلَةٌ في مَحَلِّ جَرٍّ مُضافٌ إِلَيْهِ (بَعْدَ حَيْثُ).", "Muzâfun ileyh cümlesi"]] },
 { t: "tablo", ar: "تَدْريبٌ ٢: ضَعْ كُلَّ جُمْلَةٍ مِنَ الجُمَلِ التّالِيَةِ في جُمْلَتَيْنِ مِنْ إِنْشائِكَ بِحَيْثُ تَكونُ مَرَّةً في مَحَلِّ نَصْبٍ صِفَةً وَمَرَّةً في مَحَلِّ نَصْبٍ حالًا", bas: ["الجُمْلَةُ", "صِفَةٌ في مَحَلِّ نَصْبٍ", "حالٌ في مَحَلِّ نَصْبٍ"], satir: [["خَطُّهُ جَميلٌ.", "قَرَأْتُ رِسالَةَ طالِبٍ خَطُّهُ جَميلٌ.", "قابَلْتُ الطّالِبَ خَطُّهُ جَميلٌ."], ["يُساعِدُ المَساكينَ كَثيرًا.", "أُحِبُّ رَجُلًا يُساعِدُ المَساكينَ كَثيرًا.", "رَأَيْتُ الغَنِيَّ يُساعِدُ المَساكينَ كَثيرًا."], ["أَبوهُمْ مُسافِرٌ إِلى مَكَّةَ المُكَرَّمَةِ.", "زُرْتُ أَوْلادًا أَبوهُمْ مُسافِرٌ إِلى مَكَّةَ المُكَرَّمَةِ.", "زُرْتُ الأَوْلادَ أَبوهُمْ مُسافِرٌ إِلى مَكَّةَ المُكَرَّمَةِ."], ["يَسْتَغيثانِ النّاسَ.", "رَأَيْتُ رَجُلَيْنِ يَسْتَغيثانِ النّاسَ.", "رَأَيْتُ الرَّجُلَيْنِ يَسْتَغيثانِ النّاسَ."]],
  not: "Nekre bir mef‘ûlden sonra cümle sıfat, marife bir mef‘ûlden sonra hâl olur." },
 { t: "tablo", ar: "تَدْريبٌ ٣: اجْعَلِ الجُمَلَ التّالِيَةَ مَرَّةً في مَحَلِّ رَفْعٍ، وَمَرَّةً في مَحَلِّ نَصْبٍ، وَمَرَّةً في مَحَلِّ جَرٍّ، وَمَرَّةً في مَحَلِّ جَزْمٍ في جُمَلٍ مِنْ إِنْشائِكَ", bas: ["الجُمْلَةُ", "في مَحَلِّ رَفْعٍ", "في مَحَلِّ نَصْبٍ", "في مَحَلِّ جَرٍّ", "في مَحَلِّ جَزْمٍ"], satir: [["أَخْلاقُها عالِيَةٌ", "هذِهِ الفَتاةُ أَخْلاقُها عالِيَةٌ.", "كانَتِ الفَتاةُ أَخْلاقُها عالِيَةً.", "مَرَرْتُ بِفَتاةٍ أَخْلاقُها عالِيَةٌ.", "إِنْ تُصاحِبْ هِنْدًا فَأَخْلاقُها عالِيَةٌ."], ["تُحِبُّ التَّعاوُنَ مَعَ الآخَرينَ", "أُخْتي تُحِبُّ التَّعاوُنَ مَعَ الآخَرينَ.", "رَأَيْتُ فَتاةً تُحِبُّ التَّعاوُنَ مَعَ الآخَرينَ.", "أُعْجِبْتُ بِطالِبَةٍ تُحِبُّ التَّعاوُنَ مَعَ الآخَرينَ.", "إِنْ تَعْمَلْ مَعَ أُخْتي فَهِيَ تُحِبُّ التَّعاوُنَ مَعَ الآخَرينَ."], ["أَبوهُ شَيْخٌ جَليلٌ", "هذَا الطّالِبُ أَبوهُ شَيْخٌ جَليلٌ.", "كانَ خالِدٌ أَبوهُ شَيْخٌ جَليلٌ.", "سَلَّمْتُ عَلى رَجُلٍ أَبوهُ شَيْخٌ جَليلٌ.", "إِنْ تَسْأَلْ عَنْ خالِدٍ فَأَبوهُ شَيْخٌ جَليلٌ."]],
  not: "Örnekler: merfû‘ = mübtedanın haberi; mansûb = kâne’nin haberi veya mansûb nekrenin sıfatı; mecrûr = mecrûr nekrenin sıfatı; meczûm = fa ile gelen şart cevabı." },
 { t: "acik", ar: "تَدْريبٌ ٤: اشْرَحْ مَعَ التَّمْثيلِ قَوْلَ النُّحاةِ: (الجُمَلُ بَعْدَ النَّكِراتِ صِفاتٌ، وَبَعْدَ المَعارِفِ أَحْوالٌ)", aciklama: "Önce kendin açıkla; sonra cevaba bak.", ogeler: [["الجُمَلُ بَعْدَ النَّكِراتِ صِفاتٌ، وَبَعْدَ المَعارِفِ أَحْوالٌ", "إِذا جاءَتِ الجُمْلَةُ بَعْدَ اسْمٍ نَكِرَةٍ كانَتْ صِفَةً لَهُ تَتْبَعُهُ في إِعْرابِهِ: «جاءَ رَجُلٌ يَضْحَكُ»؛ وَإِذا جاءَتْ بَعْدَ اسْمٍ مَعْرِفَةٍ كانَتْ حالًا مِنْهُ في مَحَلِّ نَصْبٍ: «جاءَ الرَّجُلُ يَضْحَكُ».", "Nekrelerden sonra cümleler sıfat, marifelerden sonra hâldir."]] },
 { t: "acik", ar: "تَدْريبٌ ٥: أَجِبْ عَنِ الأَسْئِلَةِ التّالِيَةِ", aciklama: "Önce kendin cevapla.", ogeler: [["مَتى تَكونُ الجُمْلَةُ في مَحَلِّ رَفْعٍ؟", "إِذا وَقَعَتْ خَبَرًا لِلْمُبْتَدَإِ أَوْ لِإِنَّ وَأَخَواتِها، أَوْ صِفَةً لِنَكِرَةٍ مَرْفوعَةٍ، أَوْ تابِعَةً لِجُمْلَةٍ في مَحَلِّ رَفْعٍ.", "Cümle ne zaman merfû‘ mahallindedir?"], ["مَتى تَكونُ الجُمْلَةُ في مَحَلِّ نَصْبٍ؟", "إِذا وَقَعَتْ خَبَرًا لِكانَ وَأَخَواتِها، أَوْ حالًا، أَوْ مَفْعولًا بِهِ (بَعْدَ القَوْلِ)، أَوْ صِفَةً لِنَكِرَةٍ مَنْصوبَةٍ، أَوْ تابِعَةً لِجُمْلَةٍ في مَحَلِّ نَصْبٍ.", "Cümle ne zaman mansûb mahallindedir?"], ["مَتى تَكونُ الجُمْلَةُ في مَحَلِّ جَرٍّ؟", "إِذا وَقَعَتْ مُضافًا إِلَيْهِ بَعْدَ حَيْثُ وَإِذْ وَإِذا، أَوْ صِفَةً لِنَكِرَةٍ مَجْرورَةٍ، أَوْ تابِعَةً لِجُمْلَةٍ في مَحَلِّ جَرٍّ.", "Cümle ne zaman mecrûr mahallindedir?"], ["مَتى تَكونُ الجُمْلَةُ في مَحَلِّ جَزْمٍ؟", "إِذا وَقَعَتْ جَوابًا لِشَرْطٍ جازِمٍ مَقْرونًا بِالفاءِ أَوْ إِذا الفُجائِيَّةِ.", "Cümle ne zaman meczûm mahallindedir?"]] }
] },
// ---------------- DERS 94 ----------------
{ no: 94, kisa: "فَهْمُ المَسْموعِ", ar: "فَهْمُ المَسْموعِ: هَلْ أَسْئِلَةُ طِفْلِكَ تُقْلِقُكَ؟ — لِماذَا التَّجاهُلُ؟", tr: "Dinlediğini anlama: Çocuğunun soruları seni endişelendiriyor mu? Niçin görmezden gelme?", ozet: "Çocukların çok soru sormasının olumlu yönleri, anne babaların yanlış tepkileri ve soruları görmezden gelmenin gerekçeleri ile zararları.", bloklar: [
 { t: "dinle", s: "l94a", ar: "القِسْمُ الأَوَّلُ: هَلْ أَسْئِلَةُ طِفْلِكَ تُقْلِقُكَ؟", aciklama: "Önce dinle, sonra soruları cevapla.", metin: [["هَلْ أَسْئِلَةُ طِفْلِكَ تُقْلِقُكَ؟ لِكُلِّ سُؤالٍ جَوابٌ. قَدْ يَتَصَوَّرُ بَعْضُ النّاسِ أَنَّ كَثْرَةَ أَسْئِلَةِ الطِّفْلِ مِنَ السِّماتِ السَّلْبِيَّةِ المَمْقوتَةِ الَّتي يَنْبَغِي النَّهْيُ عَنْها، وَأَصْحابُ هذَا التَّصَوُّرِ مُخْطِئونَ تَمامًا؛ فَالعَكْسُ هُوَ الصَّحيحُ؛ حَيْثُ يَجِبُ تَشْجيعُ الطِّفْلِ عَلَى الأَسْئِلَةِ؛ لِأَنَّ كَثْرَةَ الأَسْئِلَةِ وَتَنَوُّعَها مُؤَشِّرٌ مِنَ المُؤَشِّراتِ الَّتي قَدْ تَدُلُّ عَلى تَفَوُّقِ الطِّفْلِ. فَالطِّفْلُ المُتَفَوِّقُ بِطَبيعَتِهِ غالِبًا ما يَكونُ مُتَعَطِّشًا لِلْمَعْرِفَةِ، مَيّالًا إِلَى النَّقْدِ، وَيَظْهَرُ ذلِكَ في أَسْئِلَتِهِ الَّتي لا تَنْقَطِعُ، وَهِيَ غالِبًا ما تَخْرُجُ عَمّا هُوَ مَأْلوفٌ، وَتَبْعُدُ عَمّا هُوَ مُتَوَقَّعٌ.", "Çocuğunun soruları seni endişelendiriyor mu? Her sorunun bir cevabı vardır. Bazı insanlar çocuğun çok soru sormasının yasaklanması gereken, hoş olmayan olumsuz özelliklerden olduğunu düşünebilir; bu düşüncede olanlar tamamen yanılıyorlar. Doğrusu tam tersidir: Çocuk soru sormaya teşvik edilmelidir; çünkü soruların çokluğu ve çeşitliliği çocuğun üstün olduğunu gösterebilecek işaretlerden biridir. Üstün çocuk tabiatı gereği çoğunlukla bilgiye susamış ve eleştiriye meyillidir; bu, ardı arkası kesilmeyen sorularında görülür. Bu sorular çoğunlukla alışılmışın dışına çıkar ve beklenenden uzaklaşır."], ["وَتَكْشِفُ أَسْئِلَةُ الأَطْفالِ في كَثيرٍ مِنَ الأَحْيانِ عَنِ اهْتِمامِهِمْ؛ فَالطِّفْلُ حينَما يَسْأَلُ بِصورَةٍ مُسْتَمِرَّةٍ وَمُلِحَّةٍ عَنْ بَعْضِ الأَشْياءِ أَوِ المَوْضوعاتِ أَوِ المَواقِفِ أَوِ الظَّواهِرِ، يَكونُ أَكْثَرَ اهْتِمامًا بِها مِنْ تِلْكَ الأَشْياءِ أَوِ المَوْضوعاتِ أَوِ المَواقِفِ أَوِ الظَّواهِرِ الَّتي يَسْأَلُ عَنْها أَسْئِلَةً عابِرَةً. وَمِنَ الأُمورِ الَّتي تُبْرِزُ أَهَمِّيَّةَ أَسْئِلَةِ الأَطْفالِ أَنَّ عَمَلِيَّةَ التَّساؤُلِ نَفْسَها تُمَثِّلُ واحِدَةً مِنْ أَهَمِّ الاسْتِراتيجِيّاتِ الَّتي تُسْتَخْدَمُ لِتَعْليمِ الأَطْفالِ: إِمّا بِتَوْجيهِ الأَسْئِلَةِ لَهُمْ، وَإِمّا بِتَشْجيعِهِمْ وَتَدْريبِهِمْ عَلى طَرْحِ ما لَدَيْهِمْ مِنْ تَساؤُلاتٍ، وَمُحاوَلَةِ الإِجابَةِ عَنْها؛ حَيْثُ يُمْكِنُ اسْتِخْدامُ الأَسْئِلَةِ لِتَنْمِيَةِ قُدْرَةِ الأَطْفالِ عَلَى التَّفْكيرِ.", "Çocukların soruları çoğu zaman ilgilerini ortaya koyar. Çocuk bazı şeyler, konular, durumlar veya olaylar hakkında sürekli ve ısrarla sorduğunda, bunlara geçerken sorduğu şeylerden daha çok ilgi duyuyordur. Çocukların sorularının önemini gösteren şeylerden biri de soru sorma sürecinin kendisinin çocukları eğitmede kullanılan en önemli stratejilerden biri olmasıdır: ya onlara sorular yöneltmek ya da onları, sahip oldukları soruları sormaya ve cevaplamaya çalışmaya teşvik etmek ve alıştırmak. Çünkü sorular çocukların düşünme yeteneğini geliştirmek için kullanılabilir."], ["في كَثيرٍ مِنَ الأَحْيانِ تَرَى الآباءَ وَالأُمَّهاتِ يَضيقونَ ذَرْعًا بِأَطْفالِهِمْ عِنْدَما يُكْثِرونَ مِنْ طَرْحِ أَسْئِلَتِهِمْ، خُصوصًا الأَسْئِلَةَ الَّتي يَعْجِزونَ عَنْ تَقْديمِ الإِجاباتِ المُناسِبَةِ لَها؛ لِذا نَجِدُ اسْتِجاباتِ هؤُلاءِ الوالِدَيْنِ نَحْوَ أَسْئِلَةِ أَطْفالِهِمْ في مُعْظَمِها اسْتِجاباتٍ سَلْبِيَّةً، لا تُحَقِّقُ الأَهْدافَ المَرْجُوَّةَ مِنْ تِلْكَ الأَسْئِلَةِ؛ فَنَراهُمْ يُواجِهونَ هذِهِ الأَسْئِلَةَ أَحْيانًا بِالعُنْفِ وَالقَسْوَةِ، فَيَنْهَرونَ الطِّفْلَ، وَيُعاقِبونَهُ، وَيَأْمُرونَهُ بِالكَفِّ عَنْ طَرْحِ مِثْلِ هذِهِ الأَسْئِلَةِ، أَوْ يَسْتَخِفّونَ بِأَسْئِلَةِ الطِّفْلِ وَيَرْفُضونَ الإِجابَةَ عَنْها، أَوْ يَتَجاهَلونَ هذِهِ الأَسْئِلَةَ وَيُهْمِلونَها.", "Çoğu zaman anne babaların, çocukları çok soru sorduğunda, özellikle de uygun cevap vermekten aciz kaldıkları sorular karşısında bunaldıklarını görürsün. Bu yüzden bu anne babaların çocuklarının sorularına tepkilerinin çoğu, bu sorulardan beklenen hedefleri gerçekleştirmeyen olumsuz tepkilerdir: Bazen bu sorulara şiddet ve sertlikle karşılık verir, çocuğu azarlar, cezalandırır ve bu tür soruları sormayı bırakmasını emrederler; ya da çocuğun sorularını hafife alıp cevap vermeyi reddederler veya bu soruları görmezden gelip ihmal ederler."], ["وَلِلتَّخَلُّصِ مِنْ إِلْحاحِ الطِّفْلِ في طَرْحِ أَسْئِلَتِهِ يَقومُ بَعْضُ الآباءِ وَالأُمَّهاتِ بِالإِجابَةِ عَنْ هذِهِ الأَسْئِلَةِ بِإِجاباتٍ قَدْ تَكونُ غَيْرَ صادِقَةٍ، أَوْ ناقِصَةً، أَوْ مُحَرَّفَةً، أَوْ غَيْرَ دَقيقَةٍ، أَوْ غَيْرَ مُناسِبَةٍ لِمُسْتَوى تَفْكيرِ الطِّفْلِ، وَسُرْعانَ ما يَكْتَشِفُ الطِّفْلُ عَدَمَ كِفايَةِ هذِهِ الإِجاباتِ، فَيَفْقِدُ الثِّقَةَ فيمَنْ قَدَّمَ لَهُ الإِجاباتِ، وَقَدْ يَلْجَأُ فِي الحُصولِ عَلى ما يُريدُ إِلَى الأَقْرانِ أَوِ الخَدَمِ أَوْ أَيِّ مَصْدَرٍ آخَرَ قَدْ يُعْطيهِ مَعْلوماتٍ تَضُرُّهُ نَفْسِيًّا وَثَقافِيًّا. وَإِذَا اقْتَنَعَ الطِّفْلُ بِالإِجاباتِ الخاطِئَةِ الَّتي تُقَدَّمُ لَهُ، وَلَمْ يَكْتَشِفْ عَدَمَ كِفايَتِها، فَإِنَّ هذا هُوَ الخَطَرُ بِعَيْنِهِ؛ حَيْثُ يُؤَدّي ذلِكَ إِلى تَشْكيلِ تَصَوُّراتٍ خاطِئَةٍ لَدَى الطِّفْلِ عَنِ المَوْضوعاتِ وَالظَّواهِرِ الَّتي يَسْأَلُ عَنْها، الأَمْرُ الَّذي يَجْعَلُهُ يَسْلُكُ سُلوكًا خاطِئًا تُجاهَ هذِهِ الظَّواهِرِ وَتِلْكَ المَوْضوعاتِ.", "Çocuğun soru sormadaki ısrarından kurtulmak için bazı anne babalar bu sorulara doğru olmayan, eksik, çarpıtılmış, kesin olmayan veya çocuğun düşünce seviyesine uygun olmayan cevaplar verir. Çocuk bu cevapların yetersizliğini çabucak keşfeder ve cevapları verene güvenini kaybeder; istediğini elde etmek için akranlarına, hizmetçilere veya ona psikolojik ve kültürel olarak zarar verecek bilgiler verebilecek başka bir kaynağa başvurabilir. Çocuk kendisine verilen yanlış cevaplara ikna olur ve yetersizliklerini fark etmezse asıl tehlike budur; çünkü bu, çocukta sorduğu konular ve olaylar hakkında yanlış kanaatler oluşmasına yol açar; bu da onun bu olaylara ve konulara karşı yanlış davranmasına sebep olur."]], not: "Metin kayıttan yazıya geçirildi; kitapta yalnızca sorular var." },
 { t: "dy", ar: "تَدْريبٌ ١: أَجِبْ بِوَضْعِ عَلامَةِ (✓) أَوْ (✗) مِمّا سَمِعْتَ", ogeler: [["عَلَى الآباءِ وَالأُمَّهاتِ الإِجابَةُ عَنْ جَميعِ أَسْئِلَةِ أَطْفالِهِمْ.", true, "", "Anne babalar çocuklarının bütün sorularını cevaplamalıdır.", "Kayıtta açıkça bu cümle yok; ama soruları görmezden gelmenin, reddetmenin ve yanlış cevap vermenin zararları anlatıldığı için ✓ kabul edildi."], ["اسْتِخْدامُ الأَسْئِلَةِ يُنَمّي قُدْرَةَ الطِّفْلِ عَلَى التَّفْكيرِ.", true, "", "Soruların kullanılması çocuğun düşünme yeteneğini geliştirir."], ["تَكْشِفُ أَسْئِلَةُ الطُّلّابِ عَنِ اهْتِماماتِهِمْ.", true, "", "Öğrencilerin soruları ilgilerini ortaya koyar."], ["الطِّفْلُ الَّذي لا يَسْأَلُ خَيْرٌ مِنَ الطِّفْلِ الَّذي يَسْأَلُ.", false, "كَثْرَةُ الأَسْئِلَةِ مُؤَشِّرٌ عَلى تَفَوُّقِ الطِّفْلِ.", "Soru sormayan çocuk soran çocuktan daha iyidir."], ["يُجيبُ الآباءُ عَنْ أَسْئِلَةِ أَطْفالِهِمْ إِجاباتٍ صَحيحَةً دائِمًا.", false, "قَدْ يُجيبونَ إِجاباتٍ غَيْرَ صادِقَةٍ أَوْ ناقِصَةٍ أَوْ مُحَرَّفَةٍ.", "Babalar çocuklarının sorularına her zaman doğru cevap verir."], ["الطِّفْلُ لا يَكْتَشِفُ الخَطَأَ في إِجابَةِ والِدَيْهِ عَنْ أَسْئِلَتِهِ.", false, "سُرْعانَ ما يَكْتَشِفُ الطِّفْلُ عَدَمَ كِفايَةِ هذِهِ الإِجاباتِ.", "Çocuk anne babasının cevabındaki hatayı fark etmez."]] },
 { t: "secim", ar: "تَدْريبٌ ٢: اخْتَرِ الجَوابَ المُناسِبَ", ogeler: [["هذِهِ المَقالَةُ مُوَجَّهَةٌ لِـ ...", "الآباءِ وَالأُمَّهاتِ", ["الأَطْفالِ", "المُعَلِّمينَ"], "Bu makale … yöneliktir."], ["تَتَناوَلُ هذِهِ المَقالَةُ مَوْضوعَ ... الأَطْفالِ", "أَسْئِلَةِ", ["تَرْبِيَةِ", "ذَكاءِ"], "Bu makale çocukların … konusunu ele alıyor."], ["عَلَى الآباءِ وَالأُمَّهاتِ مُقابَلَةُ أَسْئِلَةِ أَطْفالِهِمْ بِـ ...", "الصَّبْرِ", ["أَسْئِلَةٍ أُخْرى", "التَّجاهُلِ"], "Anne babalar çocuklarının sorularını … karşılamalıdır.", "Kayıtta anne babaların sorulardan bunalması (يَضيقونَ ذَرْعًا) ve görmezden gelmesi eleştiriliyor; bu yüzden «sabır» seçildi."], ["كَثْرَةُ أَسْئِلَةِ الطِّفْلِ دَليلٌ عَلى ...", "ذَكائِهِ", ["جَهْلِهِ", "سَذاجَتِهِ"], "Çocuğun çok soru sorması … delildir.", "Kayıtta: üstünlüğünün (تَفَوُّق) işaretidir."], ["إِذا لَمْ يُجِبِ الآباءُ عَنْ أَسْئِلَةِ أَطْفالِهِمْ لَجَؤوا إِلى ...", "الخَدَمِ", ["المُعَلِّمينَ", "الكُتُبِ"], "Babalar cevap vermezse çocuklar …’e başvurur.", "Kayıtta: akranlara, hizmetçilere veya başka bir kaynağa."], ["قَدْ تَكْشِفُ أَسْئِلَةُ الأَطْفالِ عَنْ ...", "اهْتِمامِهِمْ", ["عِنادِهِمْ", "غَبائِهِمْ"], "Çocukların soruları … ortaya koyabilir."], ["كَثْرَةُ أَسْئِلَةِ الطِّفْلِ مِنَ الأُمورِ ...", "الإيجابِيَّةِ فيهِ", ["السَّلْبِيَّةِ فيهِ", "الَّتي لَيْسَتْ سَلْبِيَّةً وَلا إيجابِيَّةً"], "Çocuğun çok soru sorması … şeylerdendir."]] },
 { t: "dinle", s: "l94b", ar: "القِسْمُ الثّاني: لِماذَا التَّجاهُلُ؟ لِكُلِّ سُؤالٍ جَوابٌ", aciklama: "Önce dinle, sonra soruları cevapla.", metin: [["لِماذَا التَّجاهُلُ؟ وَالحَقيقَةُ أَنَّنا لَوْ أَمْعَنَّا النَّظَرَ في مَوْقِفِ الوالِدَيْنِ تُجاهَ تَساؤُلاتِ أَطْفالِهِما، لَوَجَدْنا أَنَّ هُناكَ عَديدًا مِنَ المُبَرِّراتِ الَّتي تَدْفَعُ الوالِدَيْنِ لِتَجاهُلِ أَسْئِلَةِ أَطْفالِهِما وَإِهْمالِها، أَوِ الإِجابَةِ عَنْها بِشَكْلٍ غَيْرِ مُناسِبٍ وَبِطَريقَةٍ غَيْرِ عِلْمِيَّةٍ. وَمِنْ أَهَمِّ هذِهِ المُبَرِّراتِ: (١) الاهْتِمامُ بِإِجاباتِ الأَطْفالِ أَكْثَرَ مِنْ أَسْئِلَتِهِمْ: سَعادَةُ الكِبارِ مِنَ الوالِدَيْنِ وَالمُعَلِّمينَ بِإِجاباتِ الأَطْفالِ عَنِ الأَسْئِلَةِ الَّتي يُوَجِّهونَها إِلَيْهِمْ أَكْثَرَ مِنْ سَعادَتِهِمْ بِالأَسْئِلَةِ الَّتي يَطْرَحُهَا الأَطْفالُ عَلَيْهِمْ؛ حَيْثُ تَدُلُّ إِجاباتُ الأَطْفالِ عَنْ أَسْئِلَةِ المُرَبّينَ عَلى أَنَّهُمْ - أَيِ الأَطْفالَ - قَدِ اكْتَسَبُوا القَدْرَ اللّازِمَ مِنَ المَعْرِفَةِ وَالمَعْلوماتِ. وَفِي الوَقْتِ نَفْسِهِ نَرى هؤُلاءِ المُرَبّينَ قَدْ تَعَوَّدوا عَلى عَدَمِ الاهْتِمامِ بِالأَسْئِلَةِ الَّتي يَطْرَحُهَا الأَطْفالُ، أَوْ تَجاوُزِ هذِهِ الأَسْئِلَةِ، أَوْ عَلَى الأَقَلِّ الإِجابَةِ عَنْها إِجاباتٍ غَيْرَ مُناسِبَةٍ، وَذلِكَ دونَ التَّأَمُّلِ في أَسْئِلَةِ الأَطْفالِ هذِهِ، وَالتَّعَرُّفِ إِلى عَناصِرِهَا الفِكْرِيَّةِ وَأُصولِهَا العَقْلِيَّةِ.", "Niçin görmezden gelme? Gerçek şu ki anne babanın çocuklarının sorularına karşı tutumuna dikkatle baksak, onları çocuklarının sorularını görmezden gelmeye ve ihmal etmeye ya da onlara uygun olmayan ve bilimsel olmayan bir şekilde cevap vermeye iten birçok gerekçe olduğunu görürdük. Bu gerekçelerin en önemlileri: (1) Çocukların cevaplarıyla sorularından daha çok ilgilenmek: Anne baba ve öğretmenlerden oluşan büyüklerin, çocukların kendilerine yönelttikleri sorulara verdikleri cevaplara, çocukların sorduğu sorulardan daha çok sevinmesi; çünkü çocukların eğitimcilerin sorularına verdiği cevaplar, onların gerekli bilgi miktarını kazandıklarını gösterir. Aynı zamanda bu eğitimcilerin, çocukların sorduğu sorularla ilgilenmemeye, bunları geçiştirmeye ya da en azından uygunsuz cevaplar vermeye alıştıklarını görürüz; üstelik bu soruları düşünmeden ve onların fikrî unsurlarını ve aklî temellerini tanımadan."], ["(٢) قَدْ يَسْتَهينُ الآباءُ وَالأُمَّهاتُ بِأَسْئِلَةِ الأَطْفالِ، فَلا يَهْتَمّونَ بِها، وَلا يُجيبونَ عَنْها؛ لِغَرابَةِ هذِهِ الأَسْئِلَةِ أَوْ تَفاهَتِها أَوْ عَدَمِ جِدِّيَّتِها، وَهُمْ بِذلِكَ يَتَناسَوْنَ أَنَّ مِنْ حَقِّ الأَطْفالِ أَنْ يُفَكِّروا بِطَرائِقِهِمُ الخاصَّةِ الَّتي تَمْتازُ بِالبَساطَةِ وَالوُضوحِ، وَأَنَّ هؤُلاءِ الأَطْفالَ يُطْلِقونَ أَسْئِلَتَهُمُ البَسيطَةَ السّاذَجَةَ عَنْ رَغْبَةٍ صادِقَةٍ لَدَيْهِمْ في مَعْرِفَةِ وَاكْتِشافِ العالَمِ الَّذي يُحيطُ بِهِمْ. (٣) وَقَدْ تَتَعَلَّقُ أَسْئِلَةُ الأَطْفالِ بِمَوْضوعاتٍ اجْتِماعِيَّةٍ وَأَخْلاقِيَّةٍ ضِمْنَ إِطارٍ ثَقافِيٍّ لا يَسْمَحُ بِتَناوُلِها، كَسُؤالِهِمْ عَنْ مَوْضوعِ الجِنْسِ وَالعَلاقاتِ الجِنْسِيَّةِ، خُصوصًا فِي المُجْتَمَعاتِ الَّتي لا تَتَوافَرُ فيها لَدى قِطاعٍ كَبيرٍ مِنَ الآباءِ وَالأُمَّهاتِ ثَقافَةٌ فيها، وَمِنْ ثَمَّ نَراهُمْ يُهْمِلونَ تِلْكَ الأَسْئِلَةَ، وَيَتَهَرَّبونَ مِنَ الإِجابَةِ عَنْها.", "(2) Anne babalar çocukların sorularını, bu soruların tuhaflığı, önemsizliği veya ciddi olmaması yüzünden hafife alabilir; onlarla ilgilenmez ve onlara cevap vermezler. Bununla, çocukların sadelik ve açıklıkla öne çıkan kendilerine özgü yollarla düşünme hakkı olduğunu ve bu çocukların basit, saf sorularını kendilerini çevreleyen dünyayı tanıma ve keşfetme yönündeki samimi bir arzuyla sorduklarını unutmuş olurlar. (3) Çocukların soruları, ele alınmasına izin vermeyen bir kültürel çerçeve içindeki sosyal ve ahlaki konularla ilgili olabilir; cinsellik ve cinsel ilişkiler konusundaki soruları gibi; özellikle anne babaların büyük bir kesiminin bu konuda bilgi sahibi olmadığı toplumlarda. Bu yüzden onların bu soruları ihmal ettiklerini ve cevap vermekten kaçtıklarını görürüz."], ["(٤) تَجاوُزُ أَسْئِلَةِ الأَطْفالِ حُدودَ قُدُراتِهِمُ العَقْلِيَّةِ: مِنَ الأَسْبابِ الَّتي تَدْعو بَعْضَ الآباءِ وَالأُمَّهاتِ إِلى إِهْمالِ أَسْئِلَةِ الأَطْفالِ وَعَدَمِ الإِجابَةِ عَنْها أَنْ تَكونَ هذِهِ الأَسْئِلَةُ غَيْرَ إِجْرائِيَّةٍ؛ بِمَعْنى تَجاوُزِها حُدودَ قُدُراتِ الأَطْفالِ العَقْلِيَّةِ؛ كَأَنْ يَسْأَلَ الطِّفْلُ مَثَلًا: لِماذَا القَمَرُ مُسْتَديرٌ؟ أَوْ لِماذَا المِصْباحُ مُنيرٌ؟ أَوْ لِماذا تَنْبُتُ البِذْرَةُ؟ أَوْ لِماذا أَحْمَدُ أَطْوَلُ مِنْ عَلِيٍّ؟ إِلى غَيْرِ ذلِكَ مِنَ الأَسْئِلَةِ الَّتي تَتَطَلَّبُ إِجاباتٍ عَلى دَرَجَةٍ عالِيَةٍ مِنَ التَّجْريدِ وَالصُّعوبَةِ، وَعَلى مُسْتَوًى عالٍ مِنَ التَّنْظيرِ، لا يَتَّفِقُ وَالمُسْتَوَى العَقْلِيَّ لِهؤُلاءِ الأَطْفالِ مِنْ ناحِيَةٍ، وَلا يَقْدِرُ عَلَيْهِ بَعْضُ الآباءِ مِنْ ناحِيَةٍ أُخْرى. (٥) كَثيرًا ما يَطْرَحُ الأَطْفالُ أَسْئِلَةً بِشَكْلٍ مُتَتابِعٍ مُتَعاقِبٍ مُتَلاحِقٍ دونَ انْتِظارِ الإِجابَةِ عَنْ كُلِّ سُؤالٍ مِنْ هذِهِ الأَسْئِلَةِ، وَهذا يُؤَدّي في مُعْظَمِ الأَحْيانِ إِلى صُعوبَةِ مُتابَعَةِ الآباءِ وَالأُمَّهاتِ لِهذَا السَّيْلِ الجارِفِ مِنَ الأَسْئِلَةِ، وَتَقْديمِ الإِجاباتِ المُناسِبَةِ عَنْ كُلٍّ مِنْها؛ وَلِذا فَإِنَّهُمْ يَضيقونَ بِكَثْرَةِ هذِهِ الأَسْئِلَةِ، فَيُهْمِلونَها، وَلا يُجيبونَ عَنْها بِشَكْلٍ مُناسِبٍ.", "(4) Çocukların sorularının akli kapasitelerinin sınırlarını aşması: Bazı anne babaları çocukların sorularını ihmal etmeye ve cevaplamamaya iten sebeplerden biri, bu soruların uygulanabilir olmaması, yani çocukların akli kapasitelerinin sınırlarını aşmasıdır. Mesela çocuğun ‘Ay niçin yuvarlak? Lamba niçin ışık veriyor? Tohum niçin filizleniyor? Ahmed niçin Ali’den uzun?’ diye sorması gibi; bunlar yüksek derecede soyutlama ve zorluk, yüksek düzeyde kuramsallık gerektiren, bir yandan bu çocukların akli seviyesine uymayan, öte yandan bazı anne babaların da altından kalkamadığı cevaplar ister. (5) Çocuklar çoğu zaman her birinin cevabını beklemeden art arda, peş peşe sorular sorarlar. Bu da çoğu zaman anne babaların bu sel gibi soruları takip etmesini ve her birine uygun cevaplar vermesini zorlaştırır; bu yüzden soruların çokluğundan bunalır, onları ihmal eder ve uygun şekilde cevaplamazlar."], ["مَهْما كانَتْ أَسْئِلَةُ الأَطْفالِ في صُعوبَتِها أَوْ غَرابَتِها أَوْ تَفاهَتِها أَوْ تَناوُلِها لِمَوْضوعاتٍ مُحْرِجَةٍ، فَلا يَنْبَغي لِلْوالِدَيْنِ مُقابَلَةُ تِلْكَ الأَسْئِلَةِ بِالرَّفْضِ أَوِ التَّجاهُلِ وَالإِهْمالِ، أَوِ الإِجابَةِ عَنْها بِطَريقَةٍ غَيْرِ عِلْمِيَّةٍ وَغَيْرِ مُناسِبَةٍ لِمُسْتَوى تَفْكيرِ الطِّفْلِ؛ حَيْثُ يَتَرَتَّبُ عَلى ذلِكَ عَديدٌ مِنَ النَّتائِجِ السَّلْبِيَّةِ الخَطيرَةِ: كَإِحْباطِ الطِّفْلِ، وَتَثْبيطِ هِمَّتِهِ وَحَماسِهِ، وَإِخْفاءِ مَقْدِرَتِهِ الحَقيقِيَّةِ عَلَى الحِوارِ وَالمُناقَشَةِ، وَإِغْضابِهِ، وَإِثارَةِ القَلَقِ لَدَيْهِ، فَضْلًا عَنْ زِيادَةِ شُعورِهِ بِالتَّوَتُّرِ وَالخَوْفِ وَالوَحْدَةِ وَالنَّبْذِ، الأَمْرُ الَّذي يَنْتَهي بِالطِّفْلِ إِلَى الاسْتِكانَةِ، وَالإِحْجامِ عَنْ طَرْحِ أَيِّ أَسْئِلَةٍ خَشْيَةَ تَعَرُّضِهِ لِلَّوْمِ وَالتَّوْبيخِ، أَوْ يُؤَدّي بِهِ إِلى حَجْبِ أَسْئِلَتِهِ عَنِ الكِبارِ، وَالبَحْثِ عَنْ مَصادِرَ أُخْرى تُجيبُ لَهُ عَنْ هذِهِ الأَسْئِلَةِ، مِمّا قَدْ يُزَوِّدُهُ بِمَعْلوماتٍ خاطِئَةٍ تُؤَدّي إِلى نَتائِجَ ضارَّةٍ.", "Çocukların soruları zorluk, tuhaflık, önemsizlik veya utandırıcı konuları ele alma bakımından ne durumda olursa olsun, anne babanın bu soruları reddetmesi, görmezden gelip ihmal etmesi ya da onlara bilimsel olmayan ve çocuğun düşünce seviyesine uygun olmayan bir şekilde cevap vermesi uygun değildir. Çünkü bunun birçok tehlikeli olumsuz sonucu olur: Çocuğun hayal kırıklığına uğraması, azminin ve şevkinin kırılması, diyalog ve tartışmadaki gerçek yeteneğinin gizlenmesi, öfkelendirilmesi, onda kaygı uyandırılması; ayrıca gerginlik, korku, yalnızlık ve dışlanmışlık duygusunun artması. Bu da çocuğu boyun eğmeye ve kınanma ve azarlanma korkusuyla hiçbir soru sormamaya götürür ya da sorularını büyüklerden saklamasına ve bu soruları ona cevaplayacak başka kaynaklar aramasına yol açar; bu da ona zararlı sonuçlara götüren yanlış bilgiler verebilir."]], not: "Metin kayıttan yazıya geçirildi; kitapta yalnızca sorular var." },
 { t: "dy", ar: "تَدْريبٌ ١: أَجِبْ بِوَضْعِ عَلامَةِ (✓) أَوْ (✗) مِمّا سَمِعْتَ", ogeler: [["يَتَهَرَّبُ الآباءُ مِنَ الإِجابَةِ عَنِ الأَسْئِلَةِ الجِنْسِيَّةِ.", true, "", "Babalar cinsel sorulara cevap vermekten kaçarlar."], ["قَدْ يَتَوَقَّفُ الأَطْفالُ عَنِ الأَسْئِلَةِ خَوْفًا مِنَ اللَّوْمِ.", true, "", "Çocuklar kınanma korkusuyla soru sormayı bırakabilir."], ["يُحاوِلُ الطِّفْلُ اكْتِشافَ العالَمِ عَنْ طَريقِ أَسْئِلَتِهِ.", true, "", "Çocuk sorularıyla dünyayı keşfetmeye çalışır."], ["يَطْرَحُ الأَطْفالُ أَسْئِلَةً في حُدودِ قُدُراتِهِمُ العَقْلِيَّةِ.", false, "قَدْ تَتَجاوَزُ أَسْئِلَتُهُمْ حُدودَ قُدُراتِهِمُ العَقْلِيَّةِ.", "Çocuklar akli kapasiteleri sınırında sorular sorar."], ["يَجِبُ عِقابُ الطِّفْلِ إِذا سَأَلَ عَنْ أُمورٍ جِنْسِيَّةٍ.", false, "لا يَنْبَغي مُقابَلَةُ أَسْئِلَتِهِ بِالرَّفْضِ أَوِ العِقابِ مَهْما كانَتْ مُحْرِجَةً.", "Çocuk cinsel konular sorarsa cezalandırılmalıdır."], ["يَشْعُرُ الطِّفْلُ بِالتَّوَتُّرِ وَالإِحْباطِ إِذا أُهْمِلَتْ تَساؤُلاتُهُ.", true, "", "Soruları ihmal edilirse çocuk gerginlik ve hayal kırıklığı hisseder."]] },
 { t: "secim", ar: "تَدْريبٌ ٢: اخْتَرِ الجَوابَ المُناسِبَ مِمّا سَمِعْتَ", ogeler: [["يَنْبَغي عَلَى المُعَلِّمينَ وَالآباءِ أَنْ يَفْرَحوا أَكْثَرَ بِـ ... الأَطْفالِ", "أَسْئِلَةِ", ["إِجاباتِ", "هُدوءِ"], "Öğretmenler ve babalar çocukların …’ine daha çok sevinmelidir.", "Kayıtta büyüklerin çocukların cevaplarına sorularından daha çok sevinmesi bir kusur olarak sayılıyor."], ["مِنْ أَسْبابِ إِهْمالِ الوالِدَيْنِ أَسْئِلَةَ أَطْفالِهِمْ ...", "تَجاوُزُ الأَسْئِلَةِ قُدُراتِ الأَطْفالِ العَقْلِيَّةِ", ["ضيقُ الوَقْتِ لَدَى الوالِدَيْنِ", "جَهْلُ الوالِدَيْنِ بِالإِجاباتِ"], "Anne babaların çocuklarının sorularını ihmal etme sebeplerinden biri …", "Kayıtta bu bir ara başlık olarak geçiyor (bazı babaların bu cevaplara güç yetirememesi de anılıyor)."], ["ذَكَرَ الكاتِبُ مِنَ المُبَرِّراتِ الأَساسِيَّةِ لِتَجاهُلِ الوالِدَيْنِ أَسْئِلَةَ أَطْفالِهِمْ ... مُبَرِّراتٍ", "خَمْسَةَ", ["ثَلاثَةَ", "سَبْعَةَ"], "Yazar anne babaların çocuklarının sorularını görmezden gelmesinin … temel gerekçesini andı.", "Kayıtta sayılanlar: cevaplarla sorulardan çok ilgilenmek, soruları hafife almak, cinsel/ahlaki konular, akli kapasiteyi aşan sorular ve art arda sorulan sorular."], ["إِذا وَبَّخَ الكِبارُ الصِّغارَ عَلى أَسْئِلَتِهِمْ أَدّى ذلِكَ إِلى ...", "كِلَيْهِما", ["البَحْثِ عَنْ مَصْدَرٍ آخَرَ لِلإِجابَةِ", "إِخْفاءِ الأَسْئِلَةِ عَنِ الكِبارِ"], "Büyükler küçükleri soruları yüzünden azarlarsa bu … yol açar."], ["مَثَّلَ الكاتِبُ لِلأَسْئِلَةِ الصَّعْبَةِ بِاسْتِدارَةِ ...", "القَمَرِ", ["الدّائِرَةِ", "الشَّمْسِ"], "Yazar zor sorulara …’in yuvarlaklığıyla örnek verdi."]] }
] },
// ---------------- DERS 95 ----------------
{ no: 95, kisa: "التَّعْبيرُ المُتَقَدِّمُ", ar: "التَّعْبيرُ المُتَقَدِّمُ: إِنْشادُ الشِّعْرِ وَإِلْقاؤُهُ", tr: "İleri anlatım: Şiir okuma ve inşat", ozet: "İyi bir inşadın unsurları ve Hâfız İbrâhim’in Arap dilinin ağzından yazdığı kaside.", bloklar: [
 { t: "kural", ar: "إِنْشادُ الشِّعْرِ وَإِلْقاؤُهُ", metin: "إِنْشادُ الشِّعْرِ: إِلْقاؤُهُ بِصَوْتٍ مُرْتَفِعٍ مَعَ شَيْءٍ مِنَ اللَّحْنِ وَالتَّجْويدِ. وَالإِلْقاءُ الجَيِّدُ يَعْتَمِدُ العَناصِرَ التّالِيَةَ: (١) اللُّغَةُ السَّليمَةُ وَضَبْطُ أَواخِرِ الكَلِماتِ. (٢) الأَداءُ السَّليمُ مِنْ حَيْثُ النُّطْقُ وَالنَّبْرُ وَالتَّنْغيمُ. (٣) الأَداءُ التَّمْثيلِيُّ المُعَبِّرُ بِإيصالِ وَمُراعاةِ المَعانِي الاسْتِفْهامِيَّةِ وَالتَّعَجُّبِيَّةِ وَالاسْتِنْكارِيَّةِ وَالحُزْنِ وَالسُّرورِ... إِلَخْ لِلْمُسْتَمِعِ.", tr: "Şiir inşadı: Şiiri biraz nağme ve güzel okuyuşla yüksek sesle okumaktır. İyi bir okuyuş şu unsurlara dayanır: (1) doğru dil ve kelime sonlarının (harekelerin) doğru okunması; (2) telaffuz, vurgu ve tonlama bakımından doğru icra; (3) soru, hayret, kınama, hüzün ve sevinç anlamlarını dinleyiciye ulaştıran canlı (temsilî) icra." },
 { t: "metin", ar: "تَدْريبٌ ١: أَنْشِدْ قَصيدَةَ حافِظ إِبْراهيم عَلى لِسانِ اللُّغَةِ العَرَبِيَّةِ", paragraf: [[["رَجَعْتُ لِنَفْسي فَاتَّهَمْتُ حَصاتي ... وَنادَيْتُ قَوْمي فَاحْتَسَبْتُ حَياتي / رَمَوْني بِعُقْمٍ فِي الشَّبابِ وَلَيْتَني ... عَقِمْتُ فَلَمْ أَجْزَعْ لِقَوْلِ عُداتي", "Kendime döndüm ve aklımı suçladım; kavmimi çağırdım ve hayatımı (Allah’tan) sevap umarak bıraktım. / Beni gençliğimde kısırlıkla itham ettiler; keşke kısır olsaydım da düşmanlarımın sözüne üzülmeseydim.", "m95-0"]], [["وَسِعْتُ كِتابَ اللهِ لَفْظًا وَغايَةً ... وَما ضِقْتُ عَنْ آيٍ بِهِ وَعِظاتِ / فَكَيْفَ أَضيقُ اليَوْمَ عَنْ وَصْفِ آلَةٍ ... وَتَنْسيقِ أَسْماءٍ لِمُخْتَرَعاتِ", "Allah’ın Kitabını lafzıyla ve maksadıyla kuşattım; onun âyetlerine ve öğütlerine dar gelmedim. / Bugün bir aleti tarif etmeye ve icatlara isim düzenlemeye nasıl dar gelirim?", "m95-1"]], [["أَنَا البَحْرُ في أَحْشائِهِ الدُّرُّ كامِنٌ ... فَهَلْ سَأَلُوا الغَوّاصَ عَنْ صَدَفاتي / فَيا وَيْحَكُمْ أَبْلى وَتَبْلى مَحاسِني ... وَمِنْكُمْ وَإِنْ عَزَّ الدَّواءُ أُساتي", "Ben, bağrında inciler saklı bir denizim; dalgıca sedeflerimi sordular mı? / Yazıklar olsun size! Ben eskiyorum, güzelliklerim eskiyor; oysa ilaç bulunmaz olsa da hekimlerim sizdendir.", "m95-2"]], [["فَلا تَكِلوني لِلزَّمانِ فَإِنَّني ... أَخافُ عَلَيْكُمْ أَنْ تَحينَ وَفاتي / أَرى لِرِجالِ الغَرْبِ عِزًّا وَمَنْعَةً ... وَكَمْ عَزَّ أَقْوامٌ بِعِزِّ لُغاتِ", "Beni zamana bırakmayın; ölümümün gelip çatmasından sizin adınıza korkuyorum. / Batı’nın adamlarında izzet ve güç görüyorum; nice kavimler dillerinin izzetiyle izzet buldu.", "m95-3"]], [["أَيُطْرِبُكُمْ مِنْ جانِبِ الغَرْبِ ناعِبٌ ... يُنادي بِوَأْدي في رَبيعِ حَياتي / سَقَى اللهُ في بَطْنِ الجَزيرَةِ أَعْظُمًا ... يَعِزُّ عَلَيْها أَنْ تَلينَ قَناتي", "Batı tarafından, hayatımın baharında beni diri diri gömmeye çağıran bir kuzgun sizi coşturuyor mu? / Allah, Arap yarımadasının bağrındaki o kemikleri (ataları) sulasın; mızrağımın yumuşaması (benim zayıflamam) onlara ağır gelir.", "m95-4"]], [["أَيَهْجُرُني قَوْمي عَفَا اللهُ عَنْهُمُ ... إِلى لُغَةٍ لَمْ تَتَّصِلْ بِرُواةِ / سَرَتْ لوثَةُ الإِفْرَنْجِ فيها كَما سَرى ... لُعابُ الأَفاعي في مَسيلِ فُراتِ", "Kavmim -Allah onları affetsin- beni bırakıp rivayet zinciri olmayan bir dile mi gidiyor? / Frenk bulaşığı ona, yılanların salyasının tatlı su yatağına yayılması gibi yayıldı.", "m95-5"]], [["فَجاءَتْ كَثَوْبٍ ضَمَّ سَبْعينَ رُقْعَةً ... مُشَكَّلَةَ الأَلْوانِ مُخْتَلِفاتِ / إِلى مَعْشَرِ الكُتّابِ وَالجَمْعُ حافِلٌ ... بَسَطْتُ رَجائي بَعْدَ بَسْطِ شَكاتي", "O dil, renkleri karışık ve farklı yetmiş yamayı bir araya getiren bir elbise gibi oldu. / Kalabalık bir toplulukta yazarlar topluluğuna, şikâyetimi açtıktan sonra ümidimi açıyorum.", "m95-6"]]],
  not: "Her satırda iki beyit vardır (beyitler «/» ile ayrılmıştır). Kitapta bu şiirin kaydı yok; dinleme düğmesi makine okuyuşudur. Okurken soru ve hayret anlamlarına dikkat et." },
 { t: "acik", ar: "تَدْريبٌ ٢: اخْتَرْ قَصيدَةً تُعْجِبُكَ، وَاحْفَظْها أَوِ احْفَظْ جُزْءًا مِنْها، ثُمَّ أَنْشِدْها أَمامَ زُمَلائِكَ", aciklama: "Sevdiğin bir kasideyi seç, ezberle ve arkadaşlarının önünde inşat et.", ogeler: [["قَصيدَةٌ مِنَ اخْتِيارِكَ", "(Kendi seçimin)", "Kendi seçtiğin bir kaside"]] }
] },
// ---------------- DERS 96 ----------------
{ no: 96, kisa: "الجُمَلُ الَّتي لا مَحَلَّ لَها", ar: "قَواعِدُ اللُّغَةِ (ب): الجُمَلُ الَّتي لَيْسَ لَها مَحَلٌّ مِنَ الإِعْرابِ", tr: "Dilbilgisi: İrabda mahalli olmayan cümleler", ozet: "İbtidâiyye, sıla, tefsir, ara (i‘tirâzî), kasem cevabı, câzim olmayan şartın cevabı ve bunlara tâbi cümleler.", bloklar: [
 { t: "tablo", ar: "الجُمَلُ الَّتي لَيْسَ لَها مَحَلٌّ مِنَ الإِعْرابِ", bas: ["النَّوْعُ", "الضّابِطُ", "أَمْثِلَةٌ"], satir: [["الجُمْلَةُ الابْتِدائِيَّةُ", "الَّتي يُفْتَتَحُ بِهَا الكَلامُ.", "[[المُؤْمِنُ القَوِيُّ خَيْرٌ مِنَ المُؤْمِنِ الضَّعيفِ]]."], ["الجُمْلَةُ الواقِعَةُ صِلَةً لِلْمَوْصولِ", "تَأْتي بَعْدَ الاسْمِ المَوْصولِ.", "فازَ الطّالِبُ الَّذي [[حَفِظَ القُرْآنَ]]. / أَكْرِمْ مَنْ [[يَزورُكَ]]."], ["الجُمْلَةُ المُفَسِّرَةُ لِما قَبْلَها", "تُفَسِّرُ ما قَبْلَها، وَتَأْتي غالِبًا بَعْدَ «أَنْ» أَوْ «أَيْ».", "﴿فَأَوْحَيْنا إِلَيْهِ أَنِ [[اصْنَعِ الفُلْكَ]]﴾"], ["الجُمْلَةُ المُعْتَرِضَةُ", "تَقَعُ بَيْنَ مُتَلازِمَيْنِ.", "التَّعاوُنُ - [[حَفِظَكَ اللهُ]] - مَطْلَبٌ شَرْعِيٌّ."], ["الجُمْلَةُ الواقِعَةُ جَوابًا لِلْقَسَمِ", "تَأْتي بَعْدَ القَسَمِ.", "وَاللهِ [[لَأُدافِعَنَّ عَنِ المَظْلومِ ما حَييتُ]]."], ["الجُمْلَةُ الواقِعَةُ جَوابًا لِشَرْطٍ غَيْرِ جازِمٍ، أَوْ لِشَرْطٍ جازِمٍ وَلَمْ تَقْتَرِنْ بِالفاءِ أَوْ إِذا الفُجائِيَّةِ", "جَوابُ «إِذا» وَ«لَوْ» وَنَحْوِهِما، أَوْ جَوابُ «إِنْ» إِذا لَمْ يَقْتَرِنْ بِالفاءِ أَوْ إِذا.", "إِذَا اجْتَهَدْتَ [[نَجَحْتَ فِي الاخْتِبارِ]]. / إِنْ زُرْتَني [[أَكْرَمْتُكَ]]."], ["الجُمْلَةُ التّابِعَةُ لِجُمْلَةٍ أُخْرى لَيْسَ لَها مَحَلٌّ مِنَ الإِعْرابِ", "تَأْخُذُ حُكْمَ ما تَتْبَعُهُ.", "إِذَا اجْتَهَدْتَ نَجَحْتَ [[وَأَفْلَحْتَ]]."]],
  not: "Bu cümleler müfred bir kelimenin yerini tutmadığı için irabda bir mahalleri yoktur." },
 { t: "acik", ar: "تَدْريبٌ ١: بَيِّنْ لِماذا لَيْسَ لِلْجُمَلِ الَّتي تَحْتَها خَطٌّ مَحَلٌّ مِنَ الإِعْرابِ", aciklama: "Altı çizili cümlenin neden mahalli olmadığını söyle.", ogeler: [["التَّعاوُنُ عَلَى البِرِّ وَالتَّقْوى [[وَسيلَتُنا إِلَى الأَمْنِ الاجْتِماعِيِّ]].", "جُمْلَةٌ ابْتِدائِيَّةٌ؛ لا مَحَلَّ لَها لِأَنَّها فِي ابْتِداءِ الكَلامِ.", "Başlangıç cümlesi", "Kitapta cümlenin tamamı altı çizili gibi görünüyor; cümle bütünüyle ibtidâiyyedir."], ["الَّذي [[يَدْعو إِلَى التَّعاوُنِ عَلَى البِرِّ وَالتَّقْوى]] يَسْتَحِقُّ التَّكْريمَ.", "جُمْلَةُ صِلَةِ المَوْصولِ؛ لا مَحَلَّ لَها.", "Sıla cümlesi"], ["التَّعاوُنُ عَلَى البِرِّ وَالتَّقْوى - [[حَفِظَكَ اللهُ]] - مَطْلَبٌ شَرْعِيٌّ.", "جُمْلَةٌ اعْتِراضِيَّةٌ بَيْنَ المُبْتَدَإِ وَالخَبَرِ؛ لا مَحَلَّ لَها.", "Ara cümle"], ["تَاللهِ [[لَأُناصِرَنَّ مَنْ يَدْعو إِلَى التَّعاوُنِ عَلَى البِرِّ وَالتَّقْوى]].", "جُمْلَةٌ واقِعَةٌ جَوابًا لِلْقَسَمِ؛ لا مَحَلَّ لَها.", "Kasem cevabı"], ["إِذا قُمْنا بِواجِبِ التَّعاوُنِ عَلَى البِرِّ وَالتَّقْوى [[أَصْبَحَ حَقيقَةً واقِعَةً]].", "جُمْلَةٌ واقِعَةٌ جَوابًا لِشَرْطٍ غَيْرِ جازِمٍ (إِذا)؛ لا مَحَلَّ لَها.", "Câzim olmayan şartın cevabı"], ["آمَنْتُ بِالتَّعاوُنِ عَلَى البِرِّ وَالتَّقْوى [[فَدَعَوْتُ إِلَيْهِ]].", "جُمْلَةٌ تابِعَةٌ (مَعْطوفَةٌ) لِجُمْلَةٍ لا مَحَلَّ لَها (الابْتِدائِيَّةِ)؛ فَلا مَحَلَّ لَها.", "Mahalli olmayan cümleye tâbi"], ["[[أَقْبَلَ تِلْميذٌ]] يَحْمِلُ حَقيبَتَهُ عَلى ظَهْرِهِ.", "جُمْلَةٌ ابْتِدائِيَّةٌ؛ لا مَحَلَّ لَها.", "Başlangıç cümlesi", "«يَحْمِلُ حَقيبَتَهُ» ise nekreden sonra geldiği için sıfattır (merfû‘ mahallinde)."], ["إِذَا اجْتَهَدْتَ [[نَجَحْتَ]] يا وَلَدي.", "جُمْلَةٌ واقِعَةٌ جَوابًا لِشَرْطٍ غَيْرِ جازِمٍ؛ لا مَحَلَّ لَها.", "Câzim olmayan şartın cevabı"], ["إِذا زَرَعْتَ مَعْروفًا [[حَصَدْتَ خَيْرًا]].", "جُمْلَةٌ واقِعَةٌ جَوابًا لِشَرْطٍ غَيْرِ جازِمٍ؛ لا مَحَلَّ لَها.", "Câzim olmayan şartın cevabı"], ["اسْعَ - [[رَعاكَ اللهُ]] - إِلى فِعْلِ كُلِّ خَيْرٍ تَجِدْ جَزاءَهُ.", "جُمْلَةٌ اعْتِراضِيَّةٌ (دُعائِيَّةٌ) بَيْنَ الفِعْلِ وَمُتَعَلَّقِهِ؛ لا مَحَلَّ لَها.", "Ara cümle"], ["هَلْ تَعْرِفونَ الَّذي [[كَتَبَ هذِهِ اللَّوْحَةَ الجَميلَةَ]]؟", "جُمْلَةُ صِلَةِ المَوْصولِ؛ لا مَحَلَّ لَها.", "Sıla cümlesi"], ["[[عَرَفْتُ طَريقَ العِلْمِ]] فَحَرَصْتُ عَلى سُلوكِهِ.", "جُمْلَةٌ ابْتِدائِيَّةٌ؛ لا مَحَلَّ لَها.", "Başlangıç cümlesi", "«فَحَرَصْتُ عَلى سُلوكِهِ» ona atfedildiği için o da mahallsizdir."]] },
 { t: "tablo", ar: "تَدْريبٌ ٢: اجْعَلِ الجُمَلَ التّالِيَةَ مَرَّةً لَها مَحَلٌّ مِنَ الإِعْرابِ، وَمَرَّةً لَيْسَ لَها مَحَلٌّ مِنَ الإِعْرابِ", bas: ["الجُمْلَةُ", "لَها مَحَلٌّ مِنَ الإِعْرابِ", "لَيْسَ لَها مَحَلٌّ مِنَ الإِعْرابِ"], satir: [["سَلَّمَكَ اللهُ مِنْ مُجاهِدٍ قَوِيٍّ", "قُلْتُ لِلْجُنْدِيِّ: سَلَّمَكَ اللهُ مِنْ مُجاهِدٍ قَوِيٍّ. (مَقولُ القَوْلِ، في مَحَلِّ نَصْبٍ)", "أَنْتَ - سَلَّمَكَ اللهُ مِنْ مُجاهِدٍ قَوِيٍّ - حامي الوَطَنِ. (اعْتِراضِيَّةٌ)"], ["ثَقافَتُهُ عالِيَةٌ", "هذَا الأُسْتاذُ ثَقافَتُهُ عالِيَةٌ. (خَبَرٌ)", "ثَقافَتُهُ عالِيَةٌ. (ابْتِدائِيَّةٌ) / جاءَ الَّذي ثَقافَتُهُ عالِيَةٌ. (صِلَةٌ)"], ["يُدافِعُ عَنِ المَظْلومينَ دائِمًا", "عَرَفْتُ رَجُلًا يُدافِعُ عَنِ المَظْلومينَ دائِمًا. (صِفَةٌ)", "أُحِبُّ الَّذي يُدافِعُ عَنِ المَظْلومينَ دائِمًا. (صِلَةٌ)"], ["لَأَنْصُرَنَّ المَظْلومَ ما حَييتُ", "قالَ القاضي: «لَأَنْصُرَنَّ المَظْلومَ ما حَييتُ». (مَقولُ القَوْلِ، في مَحَلِّ نَصْبٍ)", "وَاللهِ لَأَنْصُرَنَّ المَظْلومَ ما حَييتُ. (جَوابُ القَسَمِ)"], ["مَرْتَعُهُ وَخيمٌ", "الظُّلْمُ مَرْتَعُهُ وَخيمٌ. (خَبَرٌ)", "مَرْتَعُهُ وَخيمٌ. (ابْتِدائِيَّةٌ) / اجْتَنِبِ الَّذي مَرْتَعُهُ وَخيمٌ. (صِلَةٌ)"], ["يَشْكو قَسْوَةَ البَرْدِ", "رَأَيْتُ فَقيرًا يَشْكو قَسْوَةَ البَرْدِ. (صِفَةٌ)", "ساعَدْتُ الَّذي يَشْكو قَسْوَةَ البَرْدِ. (صِلَةٌ)"]],
  not: "Örnek cevaplardır; parantez içinde cümlenin türü verilmiştir." },
 { t: "acik", ar: "تَدْريبٌ ٣: مَثِّلْ لِما يَأْتي بِجُمَلٍ مِنْ إِنْشائِكَ", aciklama: "Önce kendin kur; sonra örneğe bak.", ogeler: [["جُمْلَةٌ اعْتِراضِيَّةٌ", "العِلْمُ - أَعَزَّكَ اللهُ - نورٌ.", "ara cümle"], ["جُمْلَةٌ ابْتِدائِيَّةٌ", "الصِّدْقُ مَنْجاةٌ.", "başlangıç cümlesi"], ["جُمْلَةٌ واقِعَةٌ في جَوابِ القَسَمِ", "وَاللهِ لَأُؤَدِّيَنَّ الأَمانَةَ.", "kasem cevabı"], ["جُمْلَةٌ مُفَسِّرَةٌ", "كَتَبْتُ إِلَيْهِ أَنِ احْضُرْ غَدًا.", "tefsir cümlesi"], ["جُمْلَةُ صِلَةِ المَوْصولِ", "نَجَحَ الَّذي اجْتَهَدَ.", "sıla cümlesi"], ["جُمْلَةٌ واقِعَةٌ في جَوابِ شَرْطٍ غَيْرِ جازِمٍ", "إِذا جاءَ الصَّيْفُ سافَرْنا.", "câzim olmayan şartın cevabı"]] }
] },
// ---------------- DERS 97 ----------------
{ no: 97, kisa: "القِراءَةُ المُوَسَّعَةُ", ar: "قِراءَةٌ مُوَسَّعَةٌ: المِلْيونُ", tr: "Geniş okuma: Milyon", ozet: "Ailesine milyonluk ödülü paylaşacağını söyleyen Emîne’nin, her birinin bencil cevaplarıyla sarsılması ve kâğıtları yakıp her şeyi şakaya vurması.", bloklar: [
 { t: "metin", paragraf: [[["كانَتْ أَكْثَرَ أَخَواتِها ذَكاءً وَتَأَلُّقًا؛ فَقَدْ تَأَلَّقَتْ مُنْذُ صِغَرِها. تَمَيَّزَتْ وَتَفَوَّقَتْ فِي المَدْرَسَةِ، وَفِي الجامِعَةِ، وَفِي العَمَلِ. كَما تَدَفَّقَتْ نَحْوَهُمْ حُبًّا وَدِفْئًا، رُغْمَ بُرودَةِ مَشاعِرِهِمْ نَحْوَها. أَسْرَعَتْ تُعِدُّ طَعامَ العَشاءِ أَصْنافًا مُتَعَدِّدَةً تُناسِبُ أَذْواقَ الجَميعِ؛ فَبَعْدَ قَليلٍ سَيَجْتَمِعُ شَمْلُ عائِلَتِها في بَيْتِهَا المُتَواضِعِ.", "Kardeşlerinin en zekisi ve en parlağıydı; küçüklüğünden beri parlamıştı. Okulda, üniversitede ve işte seçkin ve üstün oldu. Onların kendisine karşı duygularının soğukluğuna rağmen onlara sevgi ve sıcaklık akıttı. Herkesin zevkine uygun çeşit çeşit akşam yemeği hazırlamaya koştu; çünkü az sonra ailesi onun mütevazı evinde bir araya gelecekti.", "m97-0"]], [["عادَ زَوْجُها مُحَمَّلًا بِأَصْنافٍ مِنَ الفاكِهَةِ وَالحَلْوى، لَمْ تَكُنْ فِي اسْتِقْبالِهِ كَعادَتِها؛ بَحَثَ عَنْها، دَخَلَ غُرْفَتَها فَلَمْ يَجِدْها. ناداها: أَمينَةُ! أَمينَةُ! أَيْنَ أَنْتِ؟ سَمِعَ صَوْتَها: أَنا هُنا في غُرْفَةِ المَكْتَبِ. دَخَلَ الغُرْفَةَ مُتَسائِلًا: وَماذا تَفْعَلينَ في مِثْلِ هذَا الوَقْتِ؟ رَآها غارِقَةً خَلْفَ المَكْتَبِ، وَقَدْ تَكَدَّسَتْ أَمامَها أَوْراقٌ وَمَظاريفُ، فَسَأَلَها مُمازِحًا: لِمَ كُلُّ هذِهِ الأَوْراقِ وَالمَظاريفِ، كَأَنَّ ساعِيَ البَريدِ أَلْقى إِلَيْكِ بِجُعْبَتِهِ؟! ضَحِكَتْ، وَقالَتْ لَهُ: إِنَّها مُفاجَأَةٌ لَنْ أُخْبِرَكَ إِلّا فِي المَساءِ، حينَ يَحْضُرُ الجَميعُ. وَعِنْدَمَا اقْتَرَبَ مِنْها، أَخْفَتِ الأَوْراقَ بِيَدَيْها، وَقالَتْ لَهُ: أَرْجوكَ. لا تُضِعْ بَهْجَةَ المُفاجَأَةِ!", "Kocası çeşit çeşit meyve ve tatlıyla yüklü döndü; o, âdeti olduğu gibi onu karşılamaya çıkmadı. Onu aradı, odasına girdi, bulamadı. ‘Emîne! Emîne! Neredesin?’ diye seslendi. Sesini duydu: ‘Buradayım, çalışma odasındayım.’ Odaya merakla girdi: ‘Böyle bir vakitte ne yapıyorsun?’ Onu masanın arkasına gömülmüş, önünde kâğıtlar ve zarflar yığılmış hâlde gördü. Şakayla sordu: ‘Bu kadar kâğıt ve zarf niye? Sanki postacı çantasını sana boşaltmış?!’ Güldü ve ‘Bu bir sürpriz; ancak akşam herkes gelince sana söyleyeceğim’ dedi. Ona yaklaşınca kâğıtları elleriyle gizledi ve ‘Lütfen, sürprizin sevincini kaçırma!’ dedi.", "m97-1"]], [["دَقَّ جَرَسُ البابِ... دَخَلَ الجَميعُ دَفْعَةً واحِدَةً. أَسْرَعَتْ تُمْسِكُ يَدَ والِدَتِها، تُقَبِّلُها، تُساعِدُها؛ لِتَجْلِسَ عَلى أَقْرَبِ أَريكَةٍ، ثُمَّ قَبَّلَتْ رَأْسَ أَبيها. حاوَلَتْ أَنْ تُساعِدَهُ لِيَجْلِسَ، فَدَفَعَها قائِلًا: اتْرُكي يَدي.. أَنا ما زِلْتُ شابًّا... لَسْتُ كَأُمِّكِ العَجوزِ! ضَحِكَ الجَميعُ. تَبادَلُوا التَّحِيّاتِ وَالأَشْواقَ. أَلْقى سَلْمانُ أَصْغَرُ إِخْوَتِها ما لَدَيْهِ مِنْ طُرَفٍ. إِنَّهُ آخِرُ العُنْقودِ المُدَلَّلُ! قالَ زَوْجُها مُداعِبًا: آخِرُ نُكْتَةٍ يا جَماعَةُ، أَنَّ أَمينَةَ تُعِدُّ لَكُمْ مُفاجَأَةً! رَدَّ أَخوهَا الأَكْبَرُ: أَخْشى أَنْ تَكونَ المُفاجَأَةُ، أَلّا عَشاءَ اليَوْمَ!", "Kapı zili çaldı… Hepsi bir anda içeri girdi. Annesinin elini tutmaya koştu, öptü, en yakın koltuğa oturmasına yardım etti; sonra babasının başını öptü. Oturması için ona yardım etmeye çalıştı; babası onu itip ‘Elimi bırak.. Ben hâlâ gencim… Yaşlı annen gibi değilim!’ dedi. Herkes güldü. Selamlaştılar, özlemlerini paylaştılar. Kardeşlerinin en küçüğü Selmân bildiği şakaları anlattı. O, salkımın son ve şımarık tanesiydi! Kocası takılarak ‘Son espri, arkadaşlar: Emîne size bir sürpriz hazırlıyor!’ dedi. Büyük kardeşi ‘Korkarım sürpriz, bugün akşam yemeği olmamasıdır!’ diye karşılık verdi.", "m97-2"]], [["الْتَفّوا حَوْلَ مائِدَةِ الطَّعامِ العامِرَةِ. تَوَقَّفوا عَنِ الكَلامِ وَالضَّحِكِ، أَكَلوا بِشَهِيَّةٍ مُتَناهِيَةٍ، فَقالَ زَوْجُها مُبْتَسِمًا: عَلَيْكُمُ الآنَ أَنْ تُلْقُوا النِّكاتِ، وَعَلَيَّ أَنْ آكُلَ! رَدَّ الوالِدُ: يا لَكَ مِنْ صِهْرٍ! كَيْفَ نَتَكَلَّمُ، وَلا أَحَدَ يُجيدُ الطَّبْخَ كَما كانَتْ تُجيدُهُ زَوْجَتي، إِلَّا ابْنَتي أَمينَةُ. طَعامٌ رائِعٌ سَلِمَتْ يَداكِ. لَحَظاتٌ رائِعَةٌ تُمْطِرُ سَعادَةً وَحُبًّا.. تَشِعُّ صَفاءً وَنَقاءً. إِنَّها أَجْمَلُ أَوْقاتِها، حينَ تَرى عُرَى الأُلْفَةِ وَالمَحَبَّةِ، تُحْكِمُ وَثاقَ أُسْرَتِهَا الغالِيَةِ. إِنَّها تُحِبُّهُمْ جَميعًا. تَتَمَنّى لَهُمْ كُلَّ خَيْرٍ كَما تَتَمَنّاهُ لِنَفْسِها تَمامًا.", "Dolu sofranın etrafını sardılar. Konuşmayı ve gülmeyi bıraktılar, büyük bir iştahla yediler. Kocası gülümseyerek ‘Şimdi siz espri yapın, ben de yiyeyim!’ dedi. Baba ‘Ne damatsın sen! Kızım Emîne dışında kimse karımın yaptığı gibi güzel yemek yapamazken nasıl konuşalım? Harika bir yemek; ellerine sağlık’ diye karşılık verdi. Mutluluk ve sevgi yağdıran, berraklık ve temizlik saçan harika anlar. Ülfet ve sevgi bağlarının değerli ailesinin bağını sağlamlaştırdığını gördüğü zamanlar en güzel vakitleriydi. Hepsini seviyordu; kendisine dilediği gibi onlara da her hayrı diliyordu.", "m97-3"]], [["تَمَطّى سَلْمانُ، وَضَرَبَ بِكِلْتا يَدَيْهِ عَلى بَطْنِهِ وَقالَ: لَقَدِ امْتَلَأْتُ.. الحَمْدُ للهِ. قالَتْ لَهُ: هَيّا يا صَغيري. هَيّا كُلْ هذِهِ المُلوخِيَّةَ، طَبَخْتُها خِصّيصًا لِأَجْلِكَ. إِنَّها تُدَلِّلُهُ كَأُمِّها تَمامًا. تَشْعُرُ أَنَّ في رِضاهُ رِضا والِدَيْها عَنْها. قَدَّمَتْ لَهُ مُنْذُ صِغَرِهِ كُلَّ ما تَسْتَطيعُ. غَمَرَتْهُ حُبًّا وَدَلالًا وَمالًا، وَأَعْطَتْهُ الكَثيرَ، فَهُوَ الصَّغيرُ الأَثيرُ!", "Selmân gerindi, iki eliyle karnına vurup ‘Doydum.. Elhamdülillah’ dedi. Ona ‘Haydi küçüğüm, haydi şu mulûhiyeyi ye; onu özellikle senin için pişirdim’ dedi. Onu tıpkı annesi gibi şımartıyordu. Onun hoşnutluğunda anne babasının kendisinden hoşnutluğu olduğunu hissediyordu. Küçüklüğünden beri ona elinden gelen her şeyi sunmuştu. Onu sevgiye, şımartmaya ve paraya boğmuş, ona çok şey vermişti; çünkü o, gözde küçük kardeşti!", "m97-4"]], [["قالَ لَها: وَالآنَ أَيْنَ المُفاجَأَةُ؟ وَقَفَتْ، اسْتَعَدَّتْ لِلْمَوْقِفِ. قالَتْ لَهُمْ: أَنا مَشْغولَةٌ مُنْذُ شَهْرٍ بِحَلِّ مُسابَقاتٍ وَأَلْغازٍ، جائِزَتُها مِلْيونُ دينارٍ. صاحَ الجَميعُ: مِلْيونُ دينارٍ؟ غَيْرُ مَعْقولٍ! قالَتْ: صَدِّقوني. لَقَدِ اسْتَطَعْتُ بَعْدَ جُهْدٍ أَنْ أَفُكَّ أَلْغازَها، وَأَنْ أُجيبَ عَنْ أَسْئِلَتِهَا العِلْمِيَّةِ وَالثَّقافِيَّةِ. أَنا مُتَأَكِّدَةٌ مِنَ الحَلِّ الصَّحيحِ. قالَ سَلْمانُ: إِذَنْ سَتَفوزينَ بِالمِلْيونِ دينارٍ حَتْمًا!", "Ona ‘Şimdi sürpriz nerede?’ dedi. Ayağa kalktı, duruma hazırlandı. Onlara ‘Bir aydır ödülü bir milyon dinar olan yarışmaları ve bulmacaları çözmekle meşgulüm’ dedi. Herkes bağırdı: ‘Bir milyon dinar mı? İnanılmaz!’ ‘İnanın bana. Çabaladıktan sonra bulmacalarını çözmeyi ve bilimsel ve kültürel sorularını cevaplamayı başardım. Doğru çözümden eminim’ dedi. Selmân ‘O zaman milyon dinarı mutlaka kazanacaksın!’ dedi.", "m97-5"]], [["أَجابَتْهُ بِحِدَّةٍ: لا..لا.. لَنْ يَكونَ لي وَحْدي.. إِذا حَصَلَ، وَكُنْتُ الفائِزَةَ، تَقاسَمْتُها بِالتَّساوي مَعَكُمْ جَميعًا. لَنْ أَرْضى أَنْ يَكونَ المِلْيونُ لي وَحْدي. تَصَوَّروا! لَقَدْ كَتَبْتُ بِاسْمِ كُلِّ واحِدٍ مِنّا عَشْرَ إِجاباتٍ صَحيحَةٍ، وَوَضَعْتُها في عَشَرَةِ مَظاريفَ. سَوْفَ أُرْسِلُ سِتّينَ إِجابَةً صَحيحَةً؛ أَيْ حَسَبَ قانونِ الاحْتِمالاتِ، سَتَكونُ فُرْصَةُ الفَوْزِ لِواحِدٍ مِنّا أَكيدَةً بِإِذْنِ اللهِ. سَأَلَها عَبْدُ اللهِ: هَلْ أَنْتِ جادَّةٌ يا أَمينَةُ أَوْ تَمْزَحينَ؟ لا.. لا.. أَنا واثِقَةٌ مِنْ إِجاباتي.. عَلَى الأَقَلِّ سَيَفوزُ واحِدٌ مِنّا، وَسَنَتَقاسَمُ المِلْيونَ.", "Ona sertçe cevap verdi: ‘Hayır.. hayır.. Yalnız benim olmayacak.. Olursa ve ben kazanırsam, hepinizle eşit olarak paylaşırım. Milyonun yalnız benim olmasına razı olmam. Düşünün! Her birimizin adına on doğru cevap yazıp on zarfa koydum. Altmış doğru cevap göndereceğim; yani olasılık kanununa göre içimizden birinin kazanma şansı Allah’ın izniyle kesin olacak.’ Abdullah ona ‘Ciddi misin Emîne, yoksa şaka mı yapıyorsun?’ diye sordu. ‘Hayır.. hayır.. Cevaplarımdan eminim.. En azından içimizden biri kazanacak ve milyonu paylaşacağız.’", "m97-6"]], [["قالَ سَلْمانُ مُعْتَرِضًا: وَمَنْ قالَ لَكِ سَنَتَقاسَمُ الجائِزَةَ؟ أَنا شَخْصِيًّا لَوْ كانَ مِنْ نَصيبي، لَاحْتَفَظْتُ بِها لِنَفْسي، وَلَما أَعْطَيْتُ واحِدًا مِنْكُمْ دينارًا! قالَتْ لَهُ: أَنْتَ تَمْزَحُ. غَيْرُ مَعْقولٍ! أَجابَ بِلا مُبالاةٍ: لا..لا.. لا أَمْزَحُ إِطْلاقًا. هذا ما سَأَفْعَلُهُ! صَمَتَتْ أَمينَةُ بُرْهَةً، صَدَمَتْها أَنانِيَّةُ أَخيهَا الصَّغيرِ وَأَحْزَنَتْها. وَلكِنْ هذا ما يُتَوَقَّعُ مِنْ شابٍّ، تَعَوَّدَ أَنْ يَأْخُذَ مِنَ الجَميعِ، وَلا يُعْطي أَحَدًا. أَمّا أَخَواهَا الباقِيانِ، فَهُما مُخْتَلِفانِ تَمامًا بِالتَّأْكيدِ، وَكَذلِكَ أُمُّها وَأَبوها وَزَوْجُها.", "Selmân itiraz ederek ‘Ödülü paylaşacağımızı sana kim söyledi? Ben şahsen, bana çıksa onu kendime saklardım ve hiçbirinize bir dinar bile vermezdim!’ dedi. Ona ‘Şaka yapıyorsun. İnanılmaz!’ dedi. Umursamadan ‘Hayır.. hayır.. Hiç şaka yapmıyorum. Yapacağım budur!’ diye cevap verdi. Emîne bir an sustu; küçük kardeşinin bencilliği onu şaşkına çevirdi ve üzdü. Ama herkesten almaya alışmış, kimseye vermeyen bir gençten beklenen de buydu. Diğer iki kardeşi ise kesinlikle tamamen farklıydı; annesi, babası ve kocası da öyle.", "m97-7"]], [["تُرى ما مَوْقِفُهُمْ لَوْ حَصَلَ أَحَدُهُمْ عَلَى الجائِزَةِ؟ تَرَدَّدَتْ قَبْلَ أَنْ تَسْأَلَهُمْ جَهْرًا. خَطَرَتْ بِبالِها فِكْرَةٌ.. قالَتْ لَهُمْ: ما رَأْيُكُمْ لَوْ أَسْأَلُ كُلَّ واحِدٍ مِنْكُمْ سِرًّا: عَمّا سَيَفْعَلُهُ بِالمِلْيونِ؟ عَلَيْكُمْ أَنْ تُجيبوا بِصِدْقٍ وَصَراحَةٍ. لا تَخافوا، لَنْ أُفْشِيَ سِرَّكُمْ.. ضَحِكَ الجَميعُ؛ فَقَدْ أَعْجَبَتْهُمُ الفِكْرَةُ. تَقَدَّمَتْ مِنْ أَبيها وَسَأَلَتْهُ، فَهَمَسَ في أُذُنِها وَقالَ: سَوْفَ أَتَزَوَّجُ مِنْ شابَّةٍ، تُجَدِّدُ لي حَياتي. وَلكِنْ تَذَكَّري، هذا سِرٌّ بَيْنَنا! نَظَرَتْ إِلى أُمِّها مُشْفِقَةً، تَمَنَّتْ أَنْ يَكونَ غَيْرَ جادٍّ، كَما تَمَنَّتْ أَلّا يَكونَ المِلْيونُ مِنْ نَصيبِهِ.", "Acaba biri ödülü kazansa tutumları ne olurdu? Onlara açıkça sormadan önce tereddüt etti. Aklına bir fikir geldi.. Onlara ‘Her birinize gizlice milyonla ne yapacağını sorsam ne dersiniz? Doğrulukla ve açıkça cevap vermelisiniz. Korkmayın, sırrınızı açmayacağım..’ dedi. Herkes güldü; fikir hoşlarına gitmişti. Babasına yaklaşıp sordu; babası kulağına fısıldadı: ‘Hayatımı yenileyecek genç bir kadınla evleneceğim. Ama unutma, bu aramızda bir sır!’ Acıyarak annesine baktı; babasının ciddi olmamasını dilediği gibi milyonun ona çıkmamasını da diledi.", "m97-8"]], [["سَأَلَتْ أُمَّها بِرِفْقٍ: «وَأَنْتِ يا أَحْلى أُمٍّ». هَمَسَتِ الأُمُّ وَأَجابَتْ دونَ تَفْكيرٍ: «سَوْفَ أُهْدِي المِلْيونَ لِسَلْمانَ؛ فَهُوَ الصَّغيرُ الضَّعيفُ، وَلَمْ يَتَزَوَّجْ بَعْدُ». قالَتْ لِنَفْسِها: يا إِلهي! كَيْفَ تُؤْثِرُهُ عَلَيْنا جَميعًا. أَلَسْنا أَوْلادَها؟ كَيْفَ تُكْسِبُهُ المالَ، وَتُفْقِدُهُ مَحَبَّةَ إِخْوَتِهِ وَاحْتِرامَهُمْ؟! نَظَرَتْ إِلى أَخيهَا عَبْدِ اللهِ. إِنَّهُ الكَبيرُ العاقِلُ؛ هُوَ مَنْ تَعَوَّدَ حَمْلَ المَسْؤولِيَّةِ، وَالبَذْلَ وَالعَطاءَ. سَأَلَتْهُ بِكُلِّ حُبٍّ: وَأَنْتَ يا عَزيزي؟", "Annesine yumuşakça sordu: «Ya sen, annelerin en tatlısı?» Anne fısıldadı ve düşünmeden cevap verdi: «Milyonu Selmân’a hediye edeceğim; çünkü o küçük ve zayıf, henüz evlenmedi de.» Kendi kendine ‘Allah’ım! Onu hepimize nasıl tercih eder? Biz onun çocukları değil miyiz? Ona parayı kazandırıp kardeşlerinin sevgisini ve saygısını nasıl kaybettirir?!’ dedi. Kardeşi Abdullah’a baktı. O, akıllı büyük kardeşti; sorumluluk taşımaya, fedakârlığa ve vermeye alışmış olandı. Ona bütün sevgisiyle sordu: ‘Ya sen, canım?’", "m97-9"]], [["طَلَبَ مِنْها أَنْ تَقْتَرِبَ مِنْهُ أَكْثَرَ، وَقالَ بِصَوْتٍ لا يَكادُ يُسْمَعُ: سَأَشْتَري بَيْتًا جَديدًا. سَأَنْفَصِلُ بِزَوْجَتي وَأَوْلادي عَنْ أُمِّكِ وَأَبيكِ. أَنا مُتْعَبٌ جِدًّا مِنْ كَثْرَةِ مَسْؤولِيّاتي يا أَمينَةُ.. يا إِلهي! لَمْ تَكُنْ تَتَوَقَّعُ هذِهِ الإِجابَةَ. مُسْتَحيلٌ. إِنَّهُ مُتَضايِقٌ مِنْ وُجودِ أُمِّهِ وَأَبيهِ. يُريدُ أَنْ يَتَخَلّى عَنْ مَسْؤولِيَّتِهِ نَحْوَهُما! لَيْتَها لَمْ تَسْأَلْهُ. شَعَرَتْ بِدُوارٍ خَفيفٍ، ثُمَّ بِرَغْبَةٍ فِي التَّقَيُّؤِ. جَلَسَتْ وَالدُّنْيا تَدورُ مِنْ حَوْلِها. نَظَرَتْ إِلى أَخيهَا أَحْمَدَ إِنَّهُ.. أَمَلُهَا الأَخيرُ.. رُبَّما كانَ أَفْضَلَ مِنْ أَخَوَيْهِ. إِنَّهُ صاحِبُ مَلايينَ مُؤَكَّدًا سَيَتَقاسَمُ المِلْيونَ مَعَ الجَميعِ. لا بُدَّ أَنْ يَفْعَلَ، لَيْسَ مِنْ أَجْلِ المالِ، بَلْ لِيُشْعِلَ نَفْسَها بِصيصَ أَمَلٍ، وَوَمْضَةَ خَيْرٍ!", "Ondan kendisine daha çok yaklaşmasını istedi ve neredeyse duyulmayan bir sesle ‘Yeni bir ev alacağım. Karımı ve çocuklarımı alıp annenden ve babandan ayrılacağım. Sorumluluklarımın çokluğundan çok yoruldum Emîne..’ dedi. Allah’ım! Bu cevabı beklemiyordu. İmkânsız. Annesinin ve babasının varlığından bunalmış. Onlara karşı sorumluluğundan vazgeçmek istiyor! Keşke ona sormasaydı. Hafif bir baş dönmesi, sonra kusma isteği hissetti. Dünya etrafında dönerken oturdu. Kardeşi Ahmed’e baktı; o.. son umuduydu.. belki iki kardeşinden daha iyiydi. Kesinlikle milyonların sahibiydi; milyonu herkesle paylaşırdı. Mutlaka yapmalıydı; para için değil, içinde bir umut kıvılcımı ve bir hayır parıltısı yaksın diye!", "m97-10"]], [["تَقَدَّمَ مِنْها أَحْمَدُ وَقالَ: أَلَمْ يَأْتِ دَوْري بَعْدُ؟ ثُمَّ قالَ هامِسًا دونَ أَنْ تَسْأَلَهُ: لَوْ كَسِبْتُ المِلْيونَ، فَسَيَكونُ قَدْ جاءَ في وَقْتِهِ المُناسِبِ تَمامًا. سَأُجْري صَفْقَةً جَديدَةً، أَحْتاجُ فيها إِلى مِلْيونٍ، وَرُبَّما أَكْثَرَ! شَعَرَتْ بِالدُّوارِ مِنْ جَديدٍ. لَيْتَها لَمْ تَسْمَعْ ما سَمِعَتْ.. لَيْتَها لَمْ تَسْأَلْ، وَلَيْتَهُمْ لَمْ يُجيبوا. نَظَرَ إِلَيْها زَوْجُها بِحُبٍّ.. رُبَّما كانَ هُوَ الوَحيدَ الَّذي أَدْرَكَ أَنَّها مُتْعَبَةٌ. رُبَّما كانَ هُوَ الَّذي لَنْ يَتَخَلّى عَنْها، لَوْ رَبِحَ الجائِزَةَ.. وَلكِنْ ما يُدْريها؟.. وَمَنْ يَضْمَنُ لَها؟ نَظَرَتْ إِلَيْهِ مَلِيًّا. هَمَّتْ أَنْ تَسْأَلَهُ. تَوَقَّفَتْ. لَقَدْ خافَتْ مِنْ إِجابَتِهِ. خَشِيَتْ أَنْ يُطْفِئَ في نَفْسِها آخِرَ وَمْضَةِ حُبٍّ وَأَمَلٍ. اقْتَرَبَ مِنْها هامِسًا. أَبْعَدَتْهُ. قالَتْ لَهُ بِحِدَّةٍ: أَرْجوكَ. أَرْجوكَ لا تَتَكَلَّمْ. لا أُريدُ مِنْكَ إِجابَةً!", "Ahmed ona yaklaşıp ‘Daha sıram gelmedi mi?’ dedi. Sonra o sormadan fısıldayarak ‘Milyonu kazanırsam tam zamanında gelmiş olacak. Bir milyona, belki daha fazlasına ihtiyaç duyacağım yeni bir iş anlaşması yapacağım!’ dedi. Yeniden baş dönmesi hissetti. Keşke duyduğunu duymasaydı.. keşke sormasaydı, keşke cevap vermeselerdi. Kocası ona sevgiyle baktı.. belki de onun yorgun olduğunu fark eden tek kişi oydu. Belki ödülü kazansa onu bırakmayacak olan oydu.. Ama nereden bilecekti?.. Kim ona garanti verirdi? Ona uzun uzun baktı. Sormaya davrandı. Durdu. Cevabından korktu. İçindeki son sevgi ve umut parıltısını söndürmesinden korktu. Kocası fısıldayarak ona yaklaştı. Onu uzaklaştırdı ve sertçe ‘Lütfen. Lütfen konuşma. Senden cevap istemiyorum!’ dedi.", "m97-11"]], [["أَسْرَعَتْ إِلى غُرْفَةِ المَكْتَبِ، جَمَعَتْ كُلَّ الأَوْراقِ وَالمَظاريفِ المُتَراكِمَةِ. حَمَلَتْ كُلَّ الإِجاباتِ الَّتي تَعِبَتْ فيها شَهْرًا كامِلًا. وَأَلْقَتْ بِذلِكَ الحِمْلِ الثَّقيلِ فِي المَطْبَخِ. في سَلَّةِ المُهْمَلاتِ. وَأَشْعَلَتْ فيهِ النّارَ؛ لِتَأْكُلَهُ وَتُخْفِيَ مَعَهُ الحَقيقَةَ. نَظَرَتْ إِلَى الأَوْراقِ وَهِيَ تَحْتَرِقُ. تَلَمَّسَتْ قَلْبَهَا الأَبْيَضَ النَّظيفَ. شَعَرَتْ أَنَّ وَهَجَ النّارِ يَنْتَقِلُ إِلَيْهِ. إِنَّهُ يَحْتَرِقُ وَيَتَّشِحُ بِالسَّوادِ. بَكَتْ بِمَرارَةٍ، وَمَسَحَتْ دُموعَها بِسُرْعَةٍ. خافَتْ أَنْ يَكْتَشِفوا حَقيقَةَ أَنْفُسِهِمُ المَريضَةِ، وَقالَتْ في سِرِّها: عَلَى الإِنْسانِ أَنْ يَعيشَ مُغْمَضَ العَيْنَيْنِ في كَثيرٍ مِنَ الأَحْيانِ؛ لِتَسْتَمِرَّ الحَياةُ.", "Çalışma odasına koştu, yığılmış bütün kâğıtları ve zarfları topladı. Tam bir ay uğraştığı bütün cevapları taşıdı ve o ağır yükü mutfağa, çöp sepetine attı. Onu yiyip bitirsin ve onunla birlikte gerçeği gizlesin diye ateşe verdi. Yanarken kâğıtlara baktı. Beyaz, temiz kalbine dokundu. Ateşin parıltısının ona geçtiğini hissetti; o da yanıyor ve karalar giyiyordu. Acı acı ağladı ve gözyaşlarını çabucak sildi. Onların hasta nefislerinin gerçeğini keşfetmelerinden korktu ve içinden ‘İnsan, hayat devam etsin diye çoğu zaman gözleri kapalı yaşamalı’ dedi.", "m97-12"]], [["حَمَلَتْ صينِيَّةَ الكُنافَةِ وَوَضَعَتْها أَمامَهُمْ، وَقالَتْ: هذِهِ هِيَ المُفاجَأَةُ الَّتي أَعْدَدْتُها لَكُمْ. كانَتْ قِصَّةُ المِلْيونِ مُزاحًا! نَظَرَ إِلَيْهَا الجَميعُ مَشْدوهينَ. مَدَّتْ يَدَها لِتَأْكُلَ وَقالَتْ: هَيّا تَفَضَّلوا. نَحْنُ في أَشَدِّ الحاجَةِ إِلَى الحَلْوى لِنَمْسَحَ بِها مَرارَةَ أَفْواهِنا!", "Künefe tepsisini getirip önlerine koydu ve ‘Size hazırladığım sürpriz işte bu. Milyon hikâyesi bir şakaydı!’ dedi. Herkes ona şaşkınlıkla baktı. Yemek için elini uzattı ve ‘Haydi buyurun. Ağzımızdaki acılığı silmek için tatlıya çok muhtacız!’ dedi.", "m97-13"]]],
  not: "(Vefâ Şelebî, «Mecelletü’l-Üsre»den uyarlama.)" },
 { t: "secim", ar: "الاسْتيعابُ — تَدْريبٌ ١: اكْتُبِ اسْمَ القائِلِ بِجانِبِ العِبارَةِ المُناسِبَةِ", ogeler: [["«سَأُجْري صَفْقَةً جَديدَةً...»", "أَحْمَدُ", ["سَلْمانُ", "الأَبُ"], "Bunu kim söyledi?"], ["«لَوْ حَصَلَ، وَكُنْتُ الفائِزَةَ، لَتَقاسَمْتُها بِالتَّساوي مَعَكُمْ جَميعًا، لَنْ أَرْضى أَنْ يَكونَ المِلْيونُ لي وَحْدي»", "أَمينَةُ", ["عَبْدُ اللهِ", "أَحْمَدُ"], "Bunu kim söyledi?"], ["«سَوْفَ أُهْدِي المِلْيونَ لِسَلْمانَ، فَهُوَ الصَّغيرُ الضَّعيفُ»", "الأُمُّ", ["أَمينَةُ", "عَبْدُ اللهِ"], "Bunu kim söyledi?"], ["«سَوْفَ أَتَزَوَّجُ مِنْ شابَّةٍ، تُجَدِّدُ لي حَياتي»", "الأَبُ", ["الأُمُّ", "أَمينَةُ"], "Bunu kim söyledi?"], ["«سَأَشْتَري بَيْتًا جَديدًا»", "عَبْدُ اللهِ", ["أَحْمَدُ", "سَلْمانُ"], "Bunu kim söyledi?"], ["«لَوْ كانَ مِنْ نَصيبي، لَاحْتَفَظْتُ بِهِ لِنَفْسي، وَلَما أَعْطَيْتُ واحِدًا مِنْكُمْ دينارًا»", "سَلْمانُ", ["الأَبُ", "الأُمُّ"], "Bunu kim söyledi?"]] },
 { t: "dy", ar: "تَدْريبٌ ٢: أَجِبْ بِوَضْعِ عَلامَةِ (✓) أَوْ (✗)", ogeler: [["كانَتْ أَمينَةُ مُتَفَوِّقَةً في دِراسَتِها.", true, "", "Emîne derslerinde üstündü."], ["بَعْدَ الجامِعَةِ، تَفَرَّغَتْ أَمينَةُ لِبَيْتِها.", false, "تَمَيَّزَتْ وَتَفَوَّقَتْ فِي العَمَلِ أَيْضًا.", "Üniversiteden sonra Emîne kendini evine verdi."], ["كانَتْ أَمينَةُ كُبْرى أَفْرادِ الأُسْرَةِ.", false, "لَها أَخٌ أَكْبَرُ مِنْها (عَبْدُ اللهِ).", "Emîne ailenin en büyüğüydü.", "Metinde «أَخوهَا الأَكْبَرُ» ve «إِنَّهُ الكَبيرُ العاقِلُ» (Abdullah) geçiyor."], ["دَعَتْ أَمينَةُ أُسْرَتَها، لِتَناوُلِ العَشاءِ في بَيْتِها.", true, "", "Emîne ailesini evinde akşam yemeğine davet etti."], ["كانَتْ أَمينَةُ مَشْغولَةً فِي المَكْتَبِ، بِكِتابَةِ الرَّسائِلِ.", false, "كانَتْ مَشْغولَةً بِحَلِّ مُسابَقاتٍ وَأَلْغازٍ.", "Emîne çalışma odasında mektup yazmakla meşguldü."], ["سَلْمانُ هُوَ أَخو أَمينَةَ الصَّغيرُ.", true, "", "Selmân Emîne’nin küçük kardeşidir."], ["كانَتْ أَمينَةُ تُحِبُّ أُسْرَتَها حُبًّا شَديدًا.", true, "", "Emîne ailesini çok seviyordu."], ["كانَتِ المُفاجَأَةُ الحَقيقِيَّةُ صينِيَّةَ الكُنافَةِ.", true, "", "Gerçek sürpriz künefe tepsisiydi.", "Emîne sonunda böyle söyledi («هذِهِ هِيَ المُفاجَأَةُ»); asıl sürpriz ise ailesinin bencilliğini keşfetmesiydi. Kitabın beklediği cevap ✓ olarak alındı."], ["شَعَرَتْ أَمينَةُ في تِلْكَ اللَّيْلَةِ بِكَثيرٍ مِنَ الحُزْنِ.", true, "", "Emîne o gece çok üzüldü."], ["يُحِبُّ كُلُّ واحِدٍ مِنْ أَفْرادِ الأُسْرَةِ الخَيْرَ لِنَفْسِهِ فَحَسْبُ.", false, "أَمينَةُ كانَتْ تَتَمَنّى لَهُمْ كُلَّ خَيْرٍ كَما تَتَمَنّاهُ لِنَفْسِها.", "Ailenin her ferdi hayrı yalnızca kendisi için ister.", "Ailenin diğer fertleri bencilce cevap verdi; ama Emîne bunun dışındaydı."]] },
 { t: "acik", ar: "تَدْريبٌ ٣: أَجِبْ عَنِ الأَسْئِلَةِ التّالِيَةِ بِاخْتِصارٍ", aciklama: "Kısaca cevapla; son üç sorunun cevabı kişisel görüştür.", ogeler: [["لِماذا دَعَتْ أَمينَةُ الأُسْرَةَ إِلى بَيْتِها؟", "لِتَناوُلِ العَشاءِ، وَلِتُخْبِرَهُمْ بِالمُفاجَأَةِ (جائِزَةِ المِلْيونِ).", "Emîne aileyi evine niçin davet etti?"], ["ماذا أَعَدَّتْ لِلأُسْرَةِ في وَجْبَةِ العَشاءِ؟", "أَصْنافًا مُتَعَدِّدَةً تُناسِبُ أَذْواقَ الجَميعِ، مِنْها المُلوخِيَّةُ، ثُمَّ الكُنافَةُ.", "Akşam yemeğinde aileye ne hazırladı?"], ["لِمَ لَمْ تَسْتَقْبِلْ أَمينَةُ زَوْجَها عِنْدَما وَصَلَ؟", "لِأَنَّها كانَتْ مَشْغولَةً في غُرْفَةِ المَكْتَبِ بِأَوْراقِ المُسابَقَةِ وَمَظاريفِها.", "Emîne kocası gelince niçin karşılamadı?"], ["ما المُفاجَأَةُ الَّتي أَعَدَّتْها أَمينَةُ لِلأُسْرَةِ؟", "أَنَّها حَلَّتْ مُسابَقَةً جائِزَتُها مِلْيونُ دينارٍ، وَسَتَتَقاسَمُها مَعَهُمْ إِنْ فازَتْ.", "Emîne’nin aileye hazırladığı sürpriz neydi?"], ["كَيْفَ اسْتَقْبَلَتْ أَمينَةُ والِدَيْها؟", "أَمْسَكَتْ يَدَ أُمِّها وَقَبَّلَتْها وَساعَدَتْها عَلَى الجُلوسِ، ثُمَّ قَبَّلَتْ رَأْسَ أَبيها.", "Emîne anne babasını nasıl karşıladı?"], ["كَيْفَ كانَتْ أَمينَةُ تُعامِلُ أَخاها سَلْمانَ؟ لِماذا؟", "كانَتْ تُدَلِّلُهُ كَأُمِّها؛ لِأَنَّها تَشْعُرُ أَنَّ في رِضاهُ رِضا والِدَيْها عَنْها.", "Emîne kardeşi Selmân’a nasıl davranıyordu? Niçin?"], ["ما مَوْضوعُ المُسابَقَةِ؟", "حَلُّ أَلْغازٍ، وَالإِجابَةُ عَنْ أَسْئِلَةٍ عِلْمِيَّةٍ وَثَقافِيَّةٍ.", "Yarışmanın konusu neydi?"], ["لِماذا فَكَّرَتْ أَمينَةُ في مَوْضوعِ المُسابَقَةِ؟", "لِتَفوزَ بِالمِلْيونِ وَتَتَقاسَمَهُ مَعَ أُسْرَتِها؛ حُبًّا لَهُمْ.", "Emîne niçin yarışmayı düşündü?"], ["لِماذا تَخَلَّتْ عَنْ مَوْضوعِ المُفاجَأَةِ؟", "لِأَنَّها صُدِمَتْ بِأَنانِيَّةِ أَفْرادِ أُسْرَتِها حينَ عَرَفَتْ ما سَيَفْعَلُهُ كُلٌّ مِنْهُمْ بِالمِلْيونِ.", "Sürprizden niçin vazgeçti?"], ["لِماذا شَعَرَتْ أَمينَةُ بِالحُزْنِ في تِلْكَ اللَّيْلَةِ؟", "لِأَنَّها اكْتَشَفَتْ أَنانِيَّةَ مَنْ تُحِبُّهُمْ، وَأَنَّهُمْ لا يُبادِلونَها الحُبَّ وَالعَطاءَ.", "O gece Emîne niçin üzüldü?"], ["لِماذا كَتَبَتِ الكاتِبَةُ هذِهِ القِصَّةَ؟", "(رَأْيٌ) لِتُبَيِّنَ خَطَرَ الأَنانِيَّةِ وَحُبِّ المالِ عَلى رَوابِطِ الأُسْرَةِ، وَأَنَّ المالَ قَدْ يَكْشِفُ حَقائِقَ النُّفوسِ.", "Yazar bu hikâyeyi niçin yazdı?"], ["ضَعْ عُنْوانًا آخَرَ مُناسِبًا لِلْقِصَّةِ.", "(مِثالٌ) الأَنانِيَّةُ / المُفاجَأَةُ المُرَّةُ / صينِيَّةُ الكُنافَةِ.", "Hikâyeye başka uygun bir başlık koy."], ["هَلْ أَعْجَبَتْكَ القِصَّةُ؟ لِماذا؟", "(رَأْيٌ شَخْصِيٌّ)", "Hikâye hoşuna gitti mi? Niçin?"]] },
 { t: "acik", ar: "تَدْريبٌ ٤: صِفْ كُلَّ شَخْصِيَّةٍ مِنْ شَخْصِيّاتِ القِصَّةِ في عِبارَةٍ قَصيرَةٍ", aciklama: "Her kişiyi kısa bir ifadeyle anlat.", ogeler: [["الأَبُ", "شَيْخٌ يَظُنُّ نَفْسَهُ شابًّا، أَنانِيٌّ، يُفَكِّرُ في نَفْسِهِ.", "Baba"], ["الأُمُّ", "طَيِّبَةٌ لكِنَّها تُدَلِّلُ ابْنَها الصَّغيرَ وَتُؤْثِرُهُ عَلى إِخْوَتِهِ.", "Anne"], ["أَمينَةُ", "ذَكِيَّةٌ مُتَفَوِّقَةٌ، كَريمَةٌ مُحِبَّةٌ لِأُسْرَتِها، تُؤْثِرُهُمْ عَلى نَفْسِها.", "Emîne"], ["عَبْدُ اللهِ", "الأَخُ الأَكْبَرُ المَسْؤولُ، لكِنَّهُ مَلَّ المَسْؤولِيَّةَ وَيُريدُ التَّخَلِّيَ عَنْ والِدَيْهِ.", "Abdullah"], ["أَحْمَدُ", "تاجِرٌ غَنِيٌّ يُحِبُّ المالَ وَيُفَكِّرُ في صَفَقاتِهِ.", "Ahmed"], ["سَلْمانُ", "الأَخُ الصَّغيرُ المُدَلَّلُ، أَنانِيٌّ صَريحٌ يَأْخُذُ وَلا يُعْطي.", "Selmân"]] },
 { t: "bosluk", ar: "المُفْرَداتُ — تَدْريبٌ ١: امْلَأِ الفَراغَ بِالفِعْلِ المُناسِبِ", kutu: ["خَطَرَتْ", "كَسَبَ", "تَقاسَمَ", "تَرَدَّدَ", "تُفْشِ", "قَبَّلَ"], ogeler: [["لا ___ سِرَّ أَخيكَ.", "تُفْشِ", null, "Kardeşinin sırrını açma."], ["___ الإِخْوَةُ الجائِزَةَ.", "تَقاسَمَ", null, "Kardeşler ödülü paylaştı."], ["___ بِبالِهِ فِكْرَةٌ.", "خَطَرَتْ", null, "Aklına bir fikir geldi."], ["___ رَأْسَ أُمِّهِ.", "قَبَّلَ", null, "Annesinin başını öptü."], ["___ قَبْلَ أَنْ يَسْأَلَ.", "تَرَدَّدَ", null, "Sormadan önce tereddüt etti."], ["___ كَثيرًا مِنَ المالِ.", "كَسَبَ", null, "Çok para kazandı."]] },
 { t: "bosluk", ar: "تَدْريبٌ ٢: ضَعِ الكَلِماتِ المُشْتَقَّةَ مِنْ مادَّةِ (ج م ع) فِي الأَماكِنِ المُناسِبَةِ", kutu: ["تَجَمَّعَ", "اجْتَمَعَ", "جامِعَة", "جَميعُهُم", "جَمَعَ", "جَماعَة", "اجْتِماع", "أَجْمَعَ"], ogeler: [["___ أَحْمَدُ كُتُبًا عَديدَةً في مَكْتَبَتِهِ.", "جَمَعَ", null, "Ahmed kütüphanesinde birçok kitap topladı."], ["___ أَفْرادُ الأُسْرَةِ عَلَى اللِّقاءِ كُلَّ أُسْبوعٍ.", "أَجْمَعَ", null, "Aile fertleri her hafta buluşmada ittifak etti."], ["___ الطُّلّابُ أَمامَ مَكْتَبِ المُديرِ.", "تَجَمَّعَ", null, "Öğrenciler müdürün odası önünde toplandı."], ["سَيَكونُ الـ ___ غَدًا فِي المَساءِ.", "اجْتِماعُ", null, "Toplantı yarın akşam olacak."], ["___ الوُزَراءُ في مَكَّةَ المُكَرَّمَةِ.", "اجْتَمَعَ", null, "Bakanlar Mekke’de toplandı."], ["عَلَيْكَ بِالصَّلاةِ ___ فِي المَسْجِدِ.", "جَماعَةً", null, "Mescitte cemaatle namaza devam et."], ["وَصَلَ الأَساتِذَةُ ___.", "جَميعُهُمْ", null, "Hocaların hepsi geldi."], ["___ الإِمامِ في مَدينَةِ الرِّياضِ.", "جامِعَةُ", null, "İmam Üniversitesi Riyad’dadır."]] },
 { t: "acik", ar: "تَدْريبٌ ٣: ما مَعْنَى العِباراتِ التّالِيَةِ؟ (اسْتَعِنْ بِالمُعْجَمِ إِنْ أَرَدْتَ)", aciklama: "İfadelerin anlamını Arapça açıkla.", ogeler: [["بَصيصُ أَمَلٍ", "شَيْءٌ قَليلٌ مِنَ الأَمَلِ.", "Bir umut ışığı"], ["وَمْضَةُ حُبٍّ", "لَمْحَةٌ سَريعَةٌ مِنَ الحُبِّ.", "Bir sevgi parıltısı"], ["سَلِمَتْ يَداكِ", "دُعاءٌ بِالسَّلامَةِ شُكْرًا عَلى عَمَلٍ حَسَنٍ.", "Ellerine sağlık"], ["غَمَرَتْهُ حُبًّا وَدَلالًا وَمالًا", "أَعْطَتْهُ الكَثيرَ مِنْها حَتّى أَحاطَتْ بِهِ.", "Onu sevgiye, şımartmaya ve paraya boğdu"], ["آخِرُ العُنْقودِ المُدَلَّلُ", "أَصْغَرُ الأَوْلادِ الَّذي يُدَلَّلُ كَثيرًا.", "Ailenin şımarık en küçüğü"], ["لَحَظاتٌ تُشِعُّ صَفاءً وَنَقاءً", "لَحَظاتٌ صافِيَةٌ خالِيَةٌ مِنَ الكَدَرِ.", "Berraklık ve temizlik saçan anlar"], ["لَحَظاتٌ تُمْطِرُ سَعادَةً وَحُبًّا", "لَحَظاتٌ كَثيرَةُ السَّعادَةِ وَالحُبِّ.", "Mutluluk ve sevgi yağdıran anlar"], ["يَعيشُ مُغْمَضَ العَيْنَيْنِ", "يَتَغافَلُ عَنْ عُيوبِ النّاسِ وَلا يَتَتَبَّعُها.", "Gözleri kapalı yaşar (görmezden gelir)"]] }
] },
// ---------------- DERS 98 ----------------
{ no: 98, kisa: "الكِتابَةُ وَالبَحْثُ", ar: "الكِتابَةُ وَالبَحْثُ", tr: "Yazı ve araştırma", ozet: "«Milyon» hikâyesini yeniden yazma ve «Güven ve barış» araştırması.", bloklar: [
 { t: "acik", ar: "أَوَّلًا: الكِتابَةُ — اكْتُبْ في دَفْتَرِكَ بِأُسْلوبِكَ قِصَّةً بِعُنْوانِ: (المِلْيونُ)", aciklama: "Geniş okumadaki hikâyeyi yeniden oku; kendi üslubunla yaz ve yazarken asıl metne bakma.", ogeler: [
  ["اسْتَعِنْ بِالعَناصِرِ: وَصْفُ صاحِبَةِ القِصَّةِ (أَمينَةَ)، أَمينَةُ تَدْعو أَفْرادَ أُسْرَتِها لِتَناوُلِ العَشاءِ، أَمينَةُ تُعِدُّ مُفاجَأَةً لِأَفْرادِ أُسْرَتِها، أَمينَةُ تَسْتَقْبِلُ أَفْرادَ أُسْرَتِها بِحَرارَةٍ، حِوارٌ حَوْلَ المائِدَةِ، جائِزَةُ المِلْيونِ دينارٍ، لِمَنِ المُكافَأَةُ، ماذا سَيَفْعَلُ كُلُّ واحِدٍ بِالمِلْيونِ دينارٍ؟ أَمينَةُ تَحْرِقُ الأَوْراقَ وَالمَظاريفَ، أَمينَةُ تَبْكي مِنَ الحُزْنِ، صينِيَّةُ الكُنافَةِ.", "(Kendi yazın)", "Unsurlar: Emîne’nin tasviri, ailesini akşam yemeğine davet etmesi, sürpriz hazırlaması, ailesini sıcak karşılaması, sofra sohbeti, milyon dinarlık ödül, ödül kimin, herkes milyonla ne yapacak, kâğıtları yakması, üzüntüden ağlaması, künefe tepsisi."]] },
 { t: "acik", ar: "ثانِيًا: البَحْثُ — اكْتُبْ في دَفْتَرِكَ بَحْثًا بِعُنْوانِ: (الأَمْنُ وَالسَّلامُ)", aciklama: "Yoğun okumadaki «Güven kavramı» metnini yeniden oku; kaynaklardan ve internetten yararlan.", ogeler: [
  ["اسْتَعِنْ بِالعَناصِرِ: أَهَمِّيَّةُ الأَمْنِ وَالسَّلامِ في حَياتِنا، حُرْمَةُ قَتْلِ النَّفْسِ البَشَرِيَّةِ، انْتِشارُ الحُروبِ في هذَا العَصْرِ، حُروبٌ عادِلَةٌ وَحُروبٌ ظالِمَةٌ، أَسْبابُ انْدِلاعِ الحُروبِ، الحُروبُ فِي الدُّوَلِ الإِسْلامِيَّةِ، دَوْرُ مَجْلِسِ الأَمْنِ في نَشْرِ السَّلامِ، دَوْرُ الدُّوَلِ الكُبْرى فِي انْدِلاعِ الحُروبِ، الحُروبُ في قارَّةِ إِفْريقْيا، الحُروبُ في قارَّةِ آسْيا.", "(Kendi araştırman)", "Unsurlar: Hayatımızda güven ve barışın önemi, insan canının dokunulmazlığı, bu çağda savaşların yayılması, adil ve zalim savaşlar, savaşların çıkış sebepleri, İslâm ülkelerindeki savaşlar, Güvenlik Konseyi’nin barıştaki rolü, büyük devletlerin savaşlardaki rolü, Afrika ve Asya’daki savaşlar."],
  ["مَراجِعُ البَحْثِ: (١) مُتَطَلَّباتُ المُحافَظَةِ عَلى نِعْمَةِ الأَمْنِ وَالاسْتِقْرارِ، سُلَيْمانُ بْنُ عَبْدِ الرَّحْمنِ الحُقَيْلُ. (٢) الأَمْنُ في حَياةِ النّاسِ وَأَهَمِّيَّتُهُ فِي الإِسْلامِ، د. عَبْدُ اللهِ بْنُ عَبْدِ المُحْسِنِ التُّرْكِيُّ. (٣) السِّلْمُ وَالحَرْبُ فِي الإِسْلامِ، عَبْدُ العَزيزِ زَهْران. (٤) العَلاقاتُ الدَّوْلِيَّةُ فِي الشَّريعَةِ الإِسْلامِيَّةِ - دِراسَةٌ فِقْهِيَّةٌ مُقارَنَةٌ، عَبّاس شومان. (٥) الأَمْنُ وَالسَّلامُ فِي الإِسْلامِ، د. جَمالُ الدّينِ الرَّمادِيُّ.", "(Kaynaklar)", "Araştırma kaynakları; ayrıca internette bu başlıklarla arama yap."]] }
] }
];
